(8,0,'2026-10-27 11:04:36','2026-10-27 11:04:36','<!-- wp:group {\"className\":\"skn-required-page\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group skn-required-page\">\n	<!-- wp:paragraph {\"className\":\"skn-kicker\"} -->\n	<p class=\"skn-kicker\">PROFIL KOMUNITAS</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"level\":2,\"className\":\"skn-page-heading\"} -->\n	<h2 class=\"wp-block-heading skn-page-heading\">Tentang Studio Karya Nusa</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:paragraph {\"className\":\"skn-lead\"} -->\n	<p class=\"skn-lead\">Studio Karya Nusa adalah komunitas yang memberi ruang belajar desain visual bagi pemula. Anggota dapat berbagi ide, menampilkan karya, dan mengikuti lokakarya kreatif.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"className\":\"skn-note-line\"} -->\n	<p class=\"skn-note-line\">Lokasi operasional: Samarinda Ulu</p>\n	<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n','Profil Studio Karya Nusa','','publish','closed','closed','','profil-studio-karya-nusa','','','2026-10-27 11:04:36','2026-10-27 11:04:36','',0,'http://localhost:8080/?page_id=8',0,'page','',0),
(9,0,'2026-10-27 11:04:36','2026-10-27 11:04:36','<!-- wp:group {\"className\":\"skn-required-page\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group skn-required-page\">\n	<!-- wp:paragraph {\"className\":\"skn-kicker\"} -->\n	<p class=\"skn-kicker\">PROGRAM &amp; KEGIATAN</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:heading {\"level\":2,\"className\":\"skn-page-heading\"} -->\n	<h2 class=\"wp-block-heading skn-page-heading\">Program Kami</h2>\n	<!-- /wp:heading -->\n\n	<!-- wp:paragraph {\"className\":\"skn-lead\"} -->\n	<p class=\"skn-lead\">Program studio mencakup galeri karya komunitas, diskusi desain, dan lokakarya poster digital. Kegiatan dirancang untuk melatih komunikasi visual melalui proyek sederhana.</p>\n	<!-- /wp:paragraph -->\n\n	<!-- wp:paragraph {\"className\":\"skn-note-line skn-verify-line\"} -->\n	<p class=\"skn-note-line skn-verify-line\">Kode verifikasi: UTS-C-2511102414081</p>\n	<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n','Program Studio Karya Nusa','','publish','closed','closed','','program-studio-karya-nusa','','','2026-10-27 11:04:36','2026-10-27 11:04:36','',0,'http://localhost:8080/?page_id=9',0,'page','',0),
(10,0,'2026-10-27 11:04:37','2026-10-27 11:04:37','<!-- wp:group {\"align\":\"full\",\"className\":\"skn-hero\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull skn-hero\">\n	<!-- wp:group {\"className\":\"skn-container skn-hero-inner\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group skn-container skn-hero-inner\">\n		<!-- wp:columns {\"className\":\"skn-hero-cols\",\"isStackedOnMobile\":true} -->\n		<div class=\"wp-block-columns skn-hero-cols\">\n			<!-- wp:column {\"width\":\"56%\",\"className\":\"skn-hero-copy\"} -->\n			<div class=\"wp-block-column skn-hero-copy\" style=\"flex-basis:56%\">\n				<!-- wp:paragraph {\"className\":\"skn-hero-kicker\"} -->\n				<p class=\"skn-hero-kicker\">KOMUNITAS KREATIF • SAMARINDA ULU</p>\n				<!-- /wp:paragraph -->\n\n				<!-- wp:heading {\"level\":1,\"className\":\"skn-hero-title\"} -->\n				<h1 class=\"wp-block-heading skn-hero-title\">Studio<br>Karya Nusa</h1>\n				<!-- /wp:heading -->\n\n				<!-- wp:paragraph {\"className\":\"skn-hero-tagline\"} -->\n				<p class=\"skn-hero-tagline\">Ruang kreasi dan berbagi ide</p>\n				<!-- /wp:paragraph -->\n\n				<!-- wp:paragraph {\"className\":\"skn-hero-text\"} -->\n				<p class=\"skn-hero-text\">Wadah belajar desain visual bagi pemula: tempat berbagi ide, menampilkan karya, dan bertemu lewat lokakarya kreatif.</p>\n				<!-- /wp:paragraph -->\n\n				<!-- wp:buttons {\"className\":\"skn-hero-buttons\"} -->\n				<div class=\"wp-block-buttons skn-hero-buttons\">\n					<!-- wp:button {\"className\":\"skn-btn skn-btn-primary\"} -->\n					<div class=\"wp-block-button skn-btn skn-btn-primary\"><a class=\"wp-block-button__link wp-element-button\" href=\"/program-studio-karya-nusa/\">Jelajahi Program</a></div>\n					<!-- /wp:button -->\n\n					<!-- wp:button {\"className\":\"skn-btn skn-btn-ghost\"} -->\n					<div class=\"wp-block-button skn-btn skn-btn-ghost\"><a class=\"wp-block-button__link wp-element-button\" href=\"/category/karya-komunitas/\">Lihat Karya</a></div>\n					<!-- /wp:button -->\n				</div>\n				<!-- /wp:buttons -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column {\"width\":\"44%\",\"className\":\"skn-hero-visual\"} -->\n			<div class=\"wp-block-column skn-hero-visual\" style=\"flex-basis:44%\">\n				<!-- wp:image {\"id\":4,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"skn-hero-poster\"} -->\n				<figure class=\"wp-block-image size-large skn-hero-poster\"><img src=\"http://localhost:8080/wp-content/uploads/2026/10/c_studio.jpg\" alt=\"Poster Galeri Poster Komunitas Studio Karya Nusa\" class=\"wp-image-4\"/></figure>\n				<!-- /wp:image -->\n			</div>\n			<!-- /wp:column -->\n		</div>\n		<!-- /wp:columns -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"skn-values\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull skn-values\">\n	<!-- wp:group {\"className\":\"skn-container\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group skn-container\">\n		<!-- wp:columns {\"className\":\"skn-values-grid\"} -->\n		<div class=\"wp-block-columns skn-values-grid\">\n			<!-- wp:column -->\n			<div class=\"wp-block-column\">\n				<!-- wp:paragraph {\"className\":\"skn-value-num\"} -->\n				<p class=\"skn-value-num\">01</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:heading {\"level\":3,\"className\":\"skn-value-title\"} -->\n				<h3 class=\"wp-block-heading skn-value-title\">Belajar</h3>\n				<!-- /wp:heading -->\n				<!-- wp:paragraph -->\n				<p>Ruang aman untuk mencoba, bertanya, dan mengasah kemampuan desain visual.</p>\n				<!-- /wp:paragraph -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column -->\n			<div class=\"wp-block-column\">\n				<!-- wp:paragraph {\"className\":\"skn-value-num\"} -->\n				<p class=\"skn-value-num\">02</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:heading {\"level\":3,\"className\":\"skn-value-title\"} -->\n				<h3 class=\"wp-block-heading skn-value-title\">Berbagi</h3>\n				<!-- /wp:heading -->\n				<!-- wp:paragraph -->\n				<p>Setiap anggota punya ruang untuk menunjukkan karya dan memberi masukan.</p>\n				<!-- /wp:paragraph -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column -->\n			<div class=\"wp-block-column\">\n				<!-- wp:paragraph {\"className\":\"skn-value-num\"} -->\n				<p class=\"skn-value-num\">03</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:heading {\"level\":3,\"className\":\"skn-value-title\"} -->\n				<h3 class=\"wp-block-heading skn-value-title\">Berkarya</h3>\n				<!-- /wp:heading -->\n				<!-- wp:paragraph -->\n				<p>Dari ide sederhana menjadi poster yang punya pesan dan karakter.</p>\n				<!-- /wp:paragraph -->\n			</div>\n			<!-- /wp:column -->\n		</div>\n		<!-- /wp:columns -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"skn-programs\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull skn-programs\">\n	<!-- wp:group {\"className\":\"skn-container\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group skn-container\">\n		<!-- wp:group {\"className\":\"skn-section-head\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group skn-section-head\">\n			<!-- wp:paragraph {\"className\":\"skn-kicker\"} -->\n			<p class=\"skn-kicker\">PROGRAM KAMI</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2,\"className\":\"skn-section-title\"} -->\n			<h2 class=\"wp-block-heading skn-section-title\">Tiga ruang untuk bertumbuh</h2>\n			<!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"skn-section-lead\"} -->\n			<p class=\"skn-section-lead\">Dari melihat karya sampai membuat poster sendiri, setiap kegiatan dirancang untuk melatih komunikasi visual lewat proyek sederhana.</p>\n			<!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:columns {\"className\":\"skn-card-grid\"} -->\n		<div class=\"wp-block-columns skn-card-grid\">\n			<!-- wp:column -->\n			<div class=\"wp-block-column\">\n				<!-- wp:group {\"className\":\"skn-card\",\"layout\":{\"type\":\"default\"}} -->\n				<div class=\"wp-block-group skn-card\">\n					<!-- wp:paragraph {\"className\":\"skn-card-num\"} -->\n					<p class=\"skn-card-num\">01</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:heading {\"level\":3} -->\n					<h3 class=\"wp-block-heading\">Galeri Karya Komunitas</h3>\n					<!-- /wp:heading -->\n					<!-- wp:paragraph -->\n					<p>Pameran poster dan karya visual anggota dengan tema lingkungan sekitar.</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:paragraph {\"className\":\"skn-card-link\"} -->\n					<p class=\"skn-card-link\"><a href=\"/category/karya-komunitas/\">Lihat karya →</a></p>\n					<!-- /wp:paragraph -->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column -->\n			<div class=\"wp-block-column\">\n				<!-- wp:group {\"className\":\"skn-card\",\"layout\":{\"type\":\"default\"}} -->\n				<div class=\"wp-block-group skn-card\">\n					<!-- wp:paragraph {\"className\":\"skn-card-num\"} -->\n					<p class=\"skn-card-num\">02</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:heading {\"level\":3} -->\n					<h3 class=\"wp-block-heading\">Diskusi Desain</h3>\n					<!-- /wp:heading -->\n					<!-- wp:paragraph -->\n					<p>Ruang berbagi masukan, referensi, dan cara membaca pesan visual.</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:paragraph {\"className\":\"skn-card-link\"} -->\n					<p class=\"skn-card-link\"><a href=\"/program-studio-karya-nusa/\">Lihat program →</a></p>\n					<!-- /wp:paragraph -->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column -->\n			<div class=\"wp-block-column\">\n				<!-- wp:group {\"className\":\"skn-card\",\"layout\":{\"type\":\"default\"}} -->\n				<div class=\"wp-block-group skn-card\">\n					<!-- wp:paragraph {\"className\":\"skn-card-num\"} -->\n					<p class=\"skn-card-num\">03</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:heading {\"level\":3} -->\n					<h3 class=\"wp-block-heading\">Lokakarya Poster Digital</h3>\n					<!-- /wp:heading -->\n					<!-- wp:paragraph -->\n					<p>Belajar menyusun judul, gambar, dan pesan utama dalam satu sesi.</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:paragraph {\"className\":\"skn-card-link\"} -->\n					<p class=\"skn-card-link\"><a href=\"/category/agenda-kreatif/\">Lihat agenda →</a></p>\n					<!-- /wp:paragraph -->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:column -->\n		</div>\n		<!-- /wp:columns -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"skn-works\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull skn-works\">\n	<!-- wp:group {\"className\":\"skn-container\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group skn-container\">\n		<!-- wp:columns {\"className\":\"skn-works-grid\",\"verticalAlignment\":\"center\"} -->\n		<div class=\"wp-block-columns skn-works-grid\">\n			<!-- wp:column {\"width\":\"42%\"} -->\n			<div class=\"wp-block-column\" style=\"flex-basis:42%\">\n				<!-- wp:paragraph {\"className\":\"skn-kicker\"} -->\n				<p class=\"skn-kicker\">KARYA TERBARU</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:heading {\"level\":2,\"className\":\"skn-section-title\"} -->\n				<h2 class=\"wp-block-heading skn-section-title\">Poster dari komunitas</h2>\n				<!-- /wp:heading -->\n				<!-- wp:paragraph {\"className\":\"skn-section-lead\"} -->\n				<p class=\"skn-section-lead\">Setiap poster membawa cerita tentang lingkungan sekitar dan cara anggota menyampaikan pesannya.</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:paragraph {\"className\":\"skn-section-link\"} -->\n				<p class=\"skn-section-link\"><a href=\"/category/karya-komunitas/\">Lihat semua karya →</a></p>\n				<!-- /wp:paragraph -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column {\"width\":\"58%\"} -->\n			<div class=\"wp-block-column\" style=\"flex-basis:58%\">\n				<!-- wp:latest-posts {\"postsToShow\":1,\"categories\":[{\"id\":2,\"name\":\"Karya Komunitas\"}],\"displayPostContent\":true,\"displayPostContentRadio\":\"excerpt\",\"excerptLength\":28,\"displayFeaturedImage\":true,\"featuredImageSizeSlug\":\"large\",\"postLayout\":\"grid\",\"columns\":1,\"className\":\"skn-latest\"} /-->\n			</div>\n			<!-- /wp:column -->\n		</div>\n		<!-- /wp:columns -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"skn-agenda\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull skn-agenda\">\n	<!-- wp:group {\"className\":\"skn-container\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group skn-container\">\n		<!-- wp:columns {\"className\":\"skn-agenda-grid\",\"verticalAlignment\":\"center\"} -->\n		<div class=\"wp-block-columns skn-agenda-grid\">\n			<!-- wp:column {\"width\":\"42%\"} -->\n			<div class=\"wp-block-column\" style=\"flex-basis:42%\">\n				<!-- wp:paragraph {\"className\":\"skn-kicker skn-kicker-light\"} -->\n				<p class=\"skn-kicker skn-kicker-light\">AGENDA</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:heading {\"level\":2,\"className\":\"skn-section-title skn-section-title-light\"} -->\n				<h2 class=\"wp-block-heading skn-section-title skn-section-title-light\">Lokakarya poster digital</h2>\n				<!-- /wp:heading -->\n				<!-- wp:paragraph {\"className\":\"skn-section-lead skn-section-lead-light\"} -->\n				<p class=\"skn-section-lead skn-section-lead-light\">Jumat, 14.00 WITA — belajar menyusun judul, gambar, dan pesan utama bersama peserta pemula.</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:paragraph {\"className\":\"skn-section-link skn-section-link-light\"} -->\n				<p class=\"skn-section-link skn-section-link-light\"><a href=\"/category/agenda-kreatif/\">Lihat agenda →</a></p>\n				<!-- /wp:paragraph -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column {\"width\":\"58%\"} -->\n			<div class=\"wp-block-column\" style=\"flex-basis:58%\">\n				<!-- wp:latest-posts {\"postsToShow\":1,\"categories\":[{\"id\":3,\"name\":\"Agenda Kreatif\"}],\"displayPostContent\":true,\"displayPostContentRadio\":\"excerpt\",\"excerptLength\":26,\"displayFeaturedImage\":true,\"featuredImageSizeSlug\":\"large\",\"postLayout\":\"grid\",\"columns\":1,\"className\":\"skn-latest skn-latest-agenda\"} /-->\n			</div>\n			<!-- /wp:column -->\n		</div>\n		<!-- /wp:columns -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"skn-cta\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull skn-cta\">\n	<!-- wp:group {\"className\":\"skn-container skn-cta-inner\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group skn-container skn-cta-inner\">\n		<!-- wp:paragraph {\"className\":\"skn-kicker skn-kicker-light\"} -->\n		<p class=\"skn-kicker skn-kicker-light\">GABUNG &amp; BELAJAR</p>\n		<!-- /wp:paragraph -->\n		<!-- wp:heading {\"level\":2,\"className\":\"skn-cta-title\"} -->\n		<h2 class=\"wp-block-heading skn-cta-title\">Ruang kreasi dan berbagi ide</h2>\n		<!-- /wp:heading -->\n		<!-- wp:paragraph {\"className\":\"skn-cta-text\"} -->\n		<p class=\"skn-cta-text\">Studio Karya Nusa terbuka untuk pemula yang ingin belajar desain visual, berbagi karya, dan bertemu teman baru.</p>\n		<!-- /wp:paragraph -->\n		<!-- wp:paragraph {\"className\":\"skn-cta-actions\"} -->\n		<p class=\"skn-cta-actions\"><a class=\"skn-cta-button\" href=\"/profil-studio-karya-nusa/\">Kenali Studio →</a></p>\n		<!-- /wp:paragraph -->\n		<!-- wp:paragraph {\"className\":\"skn-cta-location\"} -->\n		<p class=\"skn-cta-location\">Samarinda Ulu • Kalimantan Timur</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n','Beranda','','publish','closed','closed','','beranda','','','2026-10-27 19:10:07','2026-10-27 11:10:07','',0,'http://localhost:808