grid\">\n			<!-- wp:column -->\n			<div class=\"wp-block-column\">\n				<!-- wp:group {\"className\":\"skn-card\",\"layout\":{\"type\":\"default\"}} -->\n				<div class=\"wp-block-group skn-card\">\n					<!-- wp:paragraph {\"className\":\"skn-card-num\"} -->\n					<p class=\"skn-card-num\">01</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:heading {\"level\":3} -->\n					<h3 class=\"wp-block-heading\">Galeri Karya Komunitas</h3>\n					<!-- /wp:heading -->\n					<!-- wp:paragraph -->\n					<p>Pameran poster dan karya visual anggota dengan tema lingkungan sekitar.</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:paragraph {\"className\":\"skn-card-link\"} -->\n					<p class=\"skn-card-link\"><a href=\"/category/karya-komunitas/\">Lihat karya →</a></p>\n					<!-- /wp:paragraph -->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column -->\n			<div class=\"wp-block-column\">\n				<!-- wp:group {\"className\":\"skn-card\",\"layout\":{\"type\":\"default\"}} -->\n				<div class=\"wp-block-group skn-card\">\n					<!-- wp:paragraph {\"className\":\"skn-card-num\"} -->\n					<p class=\"skn-card-num\">02</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:heading {\"level\":3} -->\n					<h3 class=\"wp-block-heading\">Diskusi Desain</h3>\n					<!-- /wp:heading -->\n					<!-- wp:paragraph -->\n					<p>Ruang berbagi masukan, referensi, dan cara membaca pesan visual.</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:paragraph {\"className\":\"skn-card-link\"} -->\n					<p class=\"skn-card-link\"><a href=\"/program-studio-karya-nusa/\">Lihat program →</a></p>\n					<!-- /wp:paragraph -->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column -->\n			<div class=\"wp-block-column\">\n				<!-- wp:group {\"className\":\"skn-card\",\"layout\":{\"type\":\"default\"}} -->\n				<div class=\"wp-block-group skn-card\">\n					<!-- wp:paragraph {\"className\":\"skn-card-num\"} -->\n					<p class=\"skn-card-num\">03</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:heading {\"level\":3} -->\n					<h3 class=\"wp-block-heading\">Lokakarya Poster Digital</h3>\n					<!-- /wp:heading -->\n					<!-- wp:paragraph -->\n					<p>Belajar menyusun judul, gambar, dan pesan utama dalam satu sesi.</p>\n					<!-- /wp:paragraph -->\n					<!-- wp:paragraph {\"className\":\"skn-card-link\"} -->\n					<p class=\"skn-card-link\"><a href=\"/category/agenda-kreatif/\">Lihat agenda →</a></p>\n					<!-- /wp:paragraph -->\n				</div>\n				<!-- /wp:group -->\n			</div>\n			<!-- /wp:column -->\n		</div>\n		<!-- /wp:columns -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"skn-works\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull skn-works\">\n	<!-- wp:group {\"className\":\"skn-container\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group skn-container\">\n		<!-- wp:columns {\"className\":\"skn-works-grid\",\"verticalAlignment\":\"center\"} -->\n		<div class=\"wp-block-columns skn-works-grid\">\n			<!-- wp:column {\"width\":\"42%\"} -->\n			<div class=\"wp-block-column\" style=\"flex-basis:42%\">\n				<!-- wp:paragraph {\"className\":\"skn-kicker\"} -->\n				<p class=\"skn-kicker\">KARYA TERBARU</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:heading {\"level\":2,\"className\":\"skn-section-title\"} -->\n				<h2 class=\"wp-block-heading skn-section-title\">Poster dari komunitas</h2>\n				<!-- /wp:heading -->\n				<!-- wp:paragraph {\"className\":\"skn-section-lead\"} -->\n				<p class=\"skn-section-lead\">Setiap poster membawa cerita tentang lingkungan sekitar dan cara anggota menyampaikan pesannya.</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:paragraph {\"className\":\"skn-section-link\"} -->\n				<p class=\"skn-section-link\"><a href=\"/category/karya-komunitas/\">Lihat semua karya →</a></p>\n				<!-- /wp:paragraph -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column {\"width\":\"58%\"} -->\n			<div class=\"wp-block-column\" style=\"flex-basis:58%\">\n				<!-- wp:latest-posts {\"postsToShow\":1,\"categories\":[{\"id\":2,\"name\":\"Karya Komunitas\"}],\"displayPostContent\":true,\"displayPostContentRadio\":\"excerpt\",\"excerptLength\":28,\"displayFeaturedImage\":true,\"featuredImageSizeSlug\":\"large\",\"postLayout\":\"grid\",\"columns\":1,\"className\":\"skn-latest\"} /-->\n			</div>\n			<!-- /wp:column -->\n		</div>\n		<!-- /wp:columns -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"skn-agenda\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull skn-agenda\">\n	<!-- wp:group {\"className\":\"skn-container\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group skn-container\">\n		<!-- wp:columns {\"className\":\"skn-agenda-grid\",\"verticalAlignment\":\"center\"} -->\n		<div class=\"wp-block-columns skn-agenda-grid\">\n			<!-- wp:column {\"width\":\"42%\"} -->\n			<div class=\"wp-block-column\" style=\"flex-basis:42%\">\n				<!-- wp:paragraph {\"className\":\"skn-kicker skn-kicker-light\"} -->\n				<p class=\"skn-kicker skn-kicker-light\">AGENDA</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:heading {\"level\":2,\"className\":\"skn-section-title skn-section-title-light\"} -->\n				<h2 class=\"wp-block-heading skn-section-title skn-section-title-light\">Lokakarya poster digital</h2>\n				<!-- /wp:heading -->\n				<!-- wp:paragraph {\"className\":\"skn-section-lead skn-section-lead-light\"} -->\n				<p class=\"skn-section-lead skn-section-lead-light\">Jumat, 14.00 WITA — belajar menyusun judul, gambar, dan pesan utama bersama peserta pemula.</p>\n				<!-- /wp:paragraph -->\n				<!-- wp:paragraph {\"className\":\"skn-section-link skn-section-link-light\"} -->\n				<p class=\"skn-section-link skn-section-link-light\"><a href=\"/category/agenda-kreatif/\">Lihat agenda →</a></p>\n				<!-- /wp:paragraph -->\n			</div>\n			<!-- /wp:column -->\n\n			<!-- wp:column {\"width\":\"58%\"} -->\n			<div class=\"wp-block-column\" style=\"flex-basis:58%\">\n				<!-- wp:latest-posts {\"postsToShow\":1,\"categories\":[{\"id\":3,\"name\":\"Agenda Kreatif\"}],\"displayPostContent\":true,\"displayPostContentRadio\":\"excerpt\",\"excerptLength\":26,\"displayFeaturedImage\":true,\"featuredImageSizeSlug\":\"large\",\"postLayout\":\"grid\",\"columns\":1,\"className\":\"skn-latest skn-latest-agenda\"} /-->\n			</div>\n			<!-- /wp:column -->\n		</div>\n		<!-- /wp:columns -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"align\":\"full\",\"className\":\"skn-cta\",\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group alignfull skn-cta\">\n	<!-- wp:group {\"className\":\"skn-container skn-cta-inner\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group skn-container skn-cta-inner\">\n		<!-- wp:paragraph {\"className\":\"skn-kicker skn-kicker-light\"} -->\n		<p class=\"skn-kicker skn-kicker-light\">GABUNG &amp; BELAJAR</p>\n		<!-- /wp:paragraph -->\n		<!-- wp:heading {\"level\":2,\"className\":\"skn-cta-title\"} -->\n		<h2 class=\"wp-block-heading skn-cta-title\">Ruang kreasi dan berbagi ide</h2>\n		<!-- /wp:heading -->\n		<!-- wp:paragraph {\"className\":\"skn-cta-text\"} -->\n		<p class=\"skn-cta-text\">Studio Karya Nusa terbuka untuk pemula yang ingin belajar desain visual, berbagi karya, dan bertemu teman baru.</p>\n		<!-- /wp:paragraph -->\n		<!-- wp:paragraph {\"className\":\"skn-cta-actions\"} -->\n		<p class=\"skn-cta-actions\"><a class=\"skn-cta-button\" href=\"/profil-studio-karya-nusa/\">Kenali Studio →</a></p>\n		<!-- /wp:paragraph -->\n		<!-- wp:paragraph {\"className\":\"skn-cta-location\"} -->\n		<p class=\"skn-cta-location\">Samarinda Ulu • Kalimantan Timur</p>\n		<!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n','Beranda','','inherit','closed','closed','','10-revision-v1','','','2026-10-27 19:10:07','2026-10-27 11:10:07','',10,'http://localhost:8080/?p=26',0,'revision','',0),
(27,0,'2026-10-27 19:14:25','2026-10-27 11:14:25','/* =========================================================\n   Studio Karya Nusa — custom theme styles\n   Theme: Twenty Twenty-One\n   ========================================================= */\n\n:root {\n	--skn-green: #123b32;\n	--skn-green-deep: #0c2a24;\n	--skn-cream: #f7f1e6;\n	--skn-cream-soft: #fbf7ef;\n	--skn-terra: #d97757;\n	--skn-mustard: #e3b23c;\n	--skn-ink: #1f2421;\n	--skn-muted: #5e6a63;\n	--skn-line: rgba(18, 59, 50, 0.16);\n	--skn-serif: Georgia, \"Times New Roman\", serif;\n	--skn-sans: \"Segoe UI\", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;\n\n	--global--color-primary: var(--skn-green);\n	--global--color-primary-hover: var(--skn-terra);\n	--global--color-background: var(--skn-cream);\n	--global--color-secondary: var(--skn-terra);\n	--global--color-border: var(--skn-line);\n	--global--font-primary: var(--skn-serif);\n	--global--font-secondary: var(--skn-sans);\n	--branding--title--font-family: var(--skn-serif);\n	--branding--description--font-family: var(--skn-sans);\n	--entry-header--font-family: var(--skn-serif);\n	--footer--color-text: var(--skn-cream);\n}\n\nhtml {\n	scroll-behavior: smooth;\n}\n\nbody {\n	background: var(--skn-cream);\n	color: var(--skn-ink);\n	font-family: var(--skn-sans);\n	font-size: 17px;\n	line-height: 1.75;\n	-webkit-font-smoothing: antialiased;\n}\n\n::selection {\n	background: var(--skn-terra);\n	color: var(--skn-cream);\n}\n\nh1, h2, h3, h4, h5, h6,\n.site-title,\n.entry-title,\n.page-title {\n	font-family: var(--skn-serif);\n	color: var(--skn-green);\n	line-height: 1.08;\n	letter-spacing: -0.02em;\n}\n\na {\n	color: var(--skn-green);\n	text-decoration-thickness: 1px;\n	text-underline-offset: 3px;\n}\n\na:hover,\na:focus {\n	color: var(--skn-terra);\n}\n\n/* ---------------------------------------------------------\n   Header\n   --------------------------------------------------------- */\n\n.site-header {\n	max-width: 1240px !important;\n	margin: 0 auto !important;\n	padding: 22px 32px !important;\n	display: flex !important;\n	align-items: center;\n	gap: 18px;\n	position: sticky;\n	top: 0;\n	z-index: 100;\n	background: rgba(247, 241, 230, 0.96);\n	backdrop-filter: blur(12px);\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.site-header > .site-logo {\n	width: auto !important;\n	padding: 0 !important;\n	border: 0 !important;\n	margin: 0 !important;\n	flex: 0 0 auto;\n}\n\n.site-header .custom-logo {\n	width: 54px;\n	height: 54px;\n	max-height: 54px;\n	max-width: 54px;\n	object-fit: contain;\n	border-radius: 50%;\n}\n\n.site-branding {\n	margin: 0 !important;\n	flex: 1 1 auto;\n	min-width: 0;\n}\n\n.site-title {\n	font-size: 26px !important;\n	line-height: 1.05 !important;\n	margin: 0 !important;\n	letter-spacing: -0.02em;\n}\n\n.site-title a {\n	color: var(--skn-green) !important;\n	text-decoration: none;\n}\n\n.site-description {\n	margin: 5px 0 0 !important;\n	font-size: 11px !important;\n	letter-spacing: 0.16em;\n	text-transform: uppercase;\n	color: var(--skn-muted) !important;\n	line-height: 1.4;\n}\n\n.primary-navigation {\n	margin-left: auto;\n}\n\n@media only screen and (min-width: 822px) {\n	#primary-menu-list {\n		display: flex;\n		align-items: center;\n		gap: 28px;\n		margin: 0;\n		padding: 0;\n		list-style: none;\n	}\n\n	#primary-menu-list li {\n		margin: 0;\n	}\n\n	#primary-menu-list a {\n		font-size: 12px;\n		font-weight: 600;\n		letter-spacing: 0.12em;\n		text-transform: uppercase;\n		text-decoration: none;\n		color: var(--skn-green);\n		padding: 6px 0;\n		position: relative;\n	}\n\n	#primary-menu-list a::after {\n		content: \"\";\n		position: absolute;\n		left: 0;\n		right: 0;\n		bottom: 0;\n		height: 2px;\n		background: var(--skn-terra);\n		transform: scaleX(0);\n		transform-origin: left;\n		transition: transform 0.2s ease;\n	}\n\n	#primary-menu-list a:hover::after,\n	#primary-menu-list .current-menu-item > a::after {\n		transform: scaleX(1);\n	}\n\n	#primary-menu-list .current-menu-item > a {\n		color: var(--skn-terra);\n	}\n\n	.menu-button-container {\n		display: none;\n	}\n}\n\n/* ---------------------------------------------------------\n   Home layout\n   --------------------------------------------------------- */\n\nbody.home .site-content {\n	padding: 0 !important;\n}\n\nbody.home .content-area,\nbody.home .site-main {\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\nbody.home .entry-content .wp-block-group__inner-container > *,\nbody.home .entry-content .wp-block-columns,\nbody.home .entry-content .wp-block-column,\nbody.home .entry-content .wp-block-latest-posts {\n	max-width: none !important;\n}\n\n.skn-container {\n	max-width: 1200px !important;\n	margin-left: auto !important;\n	margin-right: auto !important;\n	padding-left: 32px;\n	padding-right: 32px;\n	box-sizing: border-box;\n}\n\n.skn-container > .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Hero\n   --------------------------------------------------------- */\n\n.skn-hero {\n	background:\n		radial-gradient(circle at 82% 18%, rgba(227, 178, 60, 0.18), transparent 32%),\n		radial-gradient(circle at 12% 88%, rgba(217, 119, 87, 0.16), transparent 36%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green) 60%, #1b4d42);\n	color: var(--skn-cream);\n	padding: 92px 0 96px;\n	position: relative;\n	overflow: hidden;\n}\n\n.skn-hero::before {\n	content: \"\";\n	position: absolute;\n	inset: 0;\n	background-image: radial-gradient(rgba(247, 241, 230, 0.08) 1px, transparent 1px);\n	background-size: 26px 26px;\n	opacity: 0.35;\n	pointer-events: none;\n}\n\n.skn-hero-inner {\n	position: relative;\n	z-index: 1;\n}\n\n.skn-hero-cols {\n	align-items: center;\n	gap: 48px;\n}\n\n.skn-hero-copy {\n	padding-right: 20px;\n}\n\n.skn-hero-kicker {\n	font-size: 11px;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-mustard);\n	margin: 0 0 18px;\n	font-weight: 700;\n}\n\n.skn-hero-title {\n	font-size: clamp(56px, 7vw, 104px) !important;\n	line-height: 0.92 !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 22px !important;\n	letter-spacing: -0.045em !important;\n}\n\n.skn-hero-tagline {\n	font-family: var(--skn-serif);\n	font-size: clamp(22px, 2.4vw, 32px);\n	font-style: italic;\n	color: var(--skn-cream) !important;\n	margin: 0 0 18px;\n	line-height: 1.2;\n}\n\n.skn-hero-text {\n	font-size: 17px;\n	line-height: 1.75;\n	color: rgba(247, 241, 230, 0.78);\n	max-width: 520px;\n	margin: 0 0 32px;\n}\n\n.skn-hero-buttons {\n	gap: 14px;\n}\n\n.skn-btn .wp-block-button__link {\n	border-radius: 999px;\n	padding: 14px 26px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease;\n}\n\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link,\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link:not(:hover):not(:active) {\n	background-color: var(--skn-terra) !important;\n	color: var(--skn-cream) !important;\n	border-color: var(--skn-terra) !important;\n}\n\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link:hover {\n	background-color: var(--skn-mustard) !important;\n	color: var(--skn-green-deep) !important;\n	border-color: var(--skn-mustard) !important;\n	transform: translateY(-2px);\n}\n\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link,\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:not(:hover):not(:active) {\n	background-color: transparent !important;\n	color: var(--skn-cream) !important;\n	border-color: rgba(247, 241, 230, 0.45) !important;\n}\n\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:hover {\n	background-color: var(--skn-cream) !important;\n	color: var(--skn-green) !important;\n	border-color: var(--skn-cream) !important;\n	transform: translateY(-2px);\n}\n\n.skn-hero-visual {\n	display: flex;\n	justify-content: flex-end;\n}\n\n.skn-hero-poster {\n	margin: 0 !important;\n	width: min(100%, 420px);\n	transform: rotate(2.5deg);\n}\n\n.skn-hero-poster img {\n	width: 100%;\n	height: auto;\n	border: 10px solid var(--skn-cream);\n	border-radius: 6px;\n	box-shadow: 0 30px 70px rgba(0, 0, 0, 0.35);\n	display: block;\n}\n\n/* ---------------------------------------------------------\n   Values\n   --------------------------------------------------------- */\n\n.skn-values {\n	background: var(--skn-cream);\n	padding: 64px 0 56px;\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.skn-values-grid {\n	gap: 0;\n}\n\n.skn-values-grid .wp-block-column {\n	padding: 0 28px;\n	border-left: 1px solid var(--skn-line);\n}\n\n.skn-values-grid .wp-block-column:first-child {\n	border-left: 0;\n	padding-left: 0;\n}\n\n.skn-value-num {\n	font-family: var(--skn-serif);\n	font-size: 14px;\n	color: var(--skn-terra);\n	letter-spacing: 0.1em;\n	margin: 0 0 10px;\n}\n\n.skn-value-title {\n	font-size: 30px !important;\n	margin: 0 0 8px !important;\n}\n\n.skn-values p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0;\n	line-height: 1.65;\n}\n\n/* ---------------------------------------------------------\n   Programs\n   --------------------------------------------------------- */\n\n.skn-programs {\n	background: var(--skn-cream-soft);\n	padding: 96px 0;\n}\n\n.skn-section-head {\n	max-width: 720px !important;\n	margin: 0 0 44px !important;\n}\n\n.skn-kicker {\n	font-size: 11px;\n	font-weight: 700;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-terra);\n	margin: 0 0 12px;\n}\n\n.skn-section-title {\n	font-size: clamp(36px, 4vw, 56px) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-section-lead {\n	font-size: 17px;\n	color: var(--skn-muted);\n	line-height: 1.7;\n	margin: 0;\n	max-width: 620px;\n}\n\n.skn-card-grid {\n	gap: 24px;\n	align-items: stretch;\n}\n\n.skn-card-grid .wp-block-column {\n	display: flex;\n}\n\n.skn-card {\n	background: var(--skn-cream);\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 30px 28px 26px !important;\n	width: 100%;\n	display: flex;\n	flex-direction: column;\n	transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;\n}\n\n.skn-card:hover {\n	transform: translateY(-6px);\n	box-shadow: 0 18px 40px rgba(18, 59, 50, 0.1);\n	border-color: rgba(217, 119, 87, 0.45);\n}\n\n.skn-card-num {\n	font-family: var(--skn-serif);\n	font-size: 13px;\n	letter-spacing: 0.12em;\n	color: var(--skn-terra);\n	margin: 0 0 22px;\n}\n\n.skn-card h3 {\n	font-size: 25px !important;\n	margin: 0 0 10px !important;\n	line-height: 1.15 !important;\n}\n\n.skn-card p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0 0 18px;\n	line-height: 1.65;\n}\n\n.skn-card-link {\n	margin-top: auto !important;\n}\n\n.skn-card-link a,\n.skn-section-link a {\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.1em;\n	text-transform: uppercase;\n	text-decoration: none;\n	color: var(--skn-terra);\n	border-bottom: 1px solid rgba(217, 119, 87, 0.4);\n	padding-bottom: 2px;\n}\n\n.skn-card-link a:hover,\n.skn-section-link a:hover {\n	color: var(--skn-green);\n	border-color: var(--skn-green);\n}\n\n/* ---------------------------------------------------------\n   Works\n   --------------------------------------------------------- */\n\n.skn-works {\n	background: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-works-grid {\n	gap: 56px;\n}\n\n.skn-works .skn-section-title {\n	font-size: clamp(34px, 4vw, 52px) !important;\n}\n\n.skn-latest {\n	display: block !important;\n	margin: 0 !important;\n	padding: 0 !important;\n	list-style: none !important;\n}\n\n.skn-latest li {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 20px;\n	overflow: hidden;\n	padding: 0 !important;\n	margin: 0 !important;\n	box-shadow: 0 18px 50px rgba(18, 59, 50, 0.08);\n	display: grid;\n	grid-template-columns: 42% 1fr;\n	align-items: stretch;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image {\n	margin: 0 !important;\n	grid-row: 1 / span 2;\n	background: var(--skn-green);\n	padding: 18px;\n	display: flex;\n	align-items: center;\n	justify-content: center;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image img {\n	width: 100% !important;\n	height: auto !important;\n	max-height: 420px;\n	object-fit: contain;\n	display: block;\n	box-shadow: 0 14px 30px rgba(0, 0, 0, 0.28);\n}\n\n.skn-latest .wp-block-latest-posts__post-title {\n	display: block;\n	font-family: var(--skn-serif);\n	font-size: 30px;\n	line-height: 1.15;\n	color: var(--skn-green);\n	text-decoration: none;\n	padding: 28px 30px 0;\n}\n\n.skn-latest .wp-block-latest-posts__post-title:hover {\n	color: var(--skn-terra);\n}\n\n.skn-latest .wp-block-latest-posts__post-excerpt {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	padding: 10px 30px 28px;\n	margin: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Agenda\n   --------------------------------------------------------- */\n\n.skn-agenda {\n	background:\n		radial-gradient(circle at 90% 10%, rgba(227, 178, 60, 0.16), transparent 30%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green));\n	color: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-agenda .skn-section-title {\n	color: var(--skn-cream) !important;\n}\n\n.skn-agenda .skn-kicker {\n	color: var(--skn-mustard);\n}\n\n.skn-agenda .skn-section-lead {\n	color: rgba(247, 241, 230, 0.75);\n}\n\n.skn-agenda .skn-section-link a {\n	color: var(--skn-mustard);\n	border-color: rgba(227, 178, 60, 0.5);\n}\n\n.skn-agenda .skn-section-link a:hover {\n	color: var(--skn-cream);\n	border-color: var(--skn-cream);\n}\n\n.skn-latest-agenda li {\n	background: #fffaf2;\n}\n\n/* ---------------------------------------------------------\n   CTA\n   --------------------------------------------------------- */\n\n.skn-cta {\n	background:\n		radial-gradient(circle at 15% 20%, rgba(247, 241, 230, 0.12), transparent 30%),\n		var(--skn-terra);\n	color: var(--skn-cream);\n	padding: 88px 0;\n	text-align: center;\n}\n\n.skn-cta-inner {\n	max-width: 820px !important;\n}\n\n.skn-cta .skn-kicker {\n	color: var(--skn-green-deep);\n}\n\n.skn-cta-title {\n	font-size: clamp(40px, 5vw, 64px) !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-cta-text {\n	font-size: 18px;\n	color: rgba(247, 241, 230, 0.85);\n	max-width: 620px;\n	margin: 0 auto 28px;\n}\n\n.skn-cta-actions {\n	margin: 0 0 24px !important;\n}\n\n.skn-cta-button {\n	display: inline-block;\n	background: var(--skn-cream);\n	color: var(--skn-green) !important;\n	border-radius: 999px;\n	padding: 14px 30px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease;\n}\n\n.skn-cta-button:hover {\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	transform: translateY(-2px);\n}\n\n.skn-cta-location {\n	font-size: 11px;\n	letter-spacing: 0.18em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.65);\n	margin: 0;\n}\n\n/* ---------------------------------------------------------\n   Required pages\n   --------------------------------------------------------- */\n\n.page .site-main,\n.single .site-main {\n	padding-top: 0;\n}\n\n.page .entry-header,\n.single .entry-header {\n	max-width: 900px !important;\n	margin: 56px auto 0 !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-title,\n.single .entry-title {\n	font-size: clamp(42px, 6vw, 72px) !important;\n	line-height: 0.98 !important;\n	margin: 0 !important;\n	color: var(--skn-green);\n}\n\n.page .entry-content,\n.single .entry-content {\n	max-width: 760px !important;\n	margin: 32px auto 72px !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-content > *,\n.single .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.page .entry-content .wp-block-group__inner-container > *,\n.single .entry-content .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.skn-required-page {\n	position: relative;\n}\n\n.skn-page-heading {\n	font-size: clamp(34px, 4.5vw, 52px) !important;\n	margin: 0 0 18px !important;\n}\n\n.skn-lead {\n	font-size: 20px !important;\n	line-height: 1.7 !important;\n	color: var(--skn-ink) !important;\n}\n\n.skn-note-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-terra);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-size: 16px !important;\n	font-weight: 600;\n	color: var(--skn-green) !important;\n	margin: 28px 0 0 !important;\n}\n\n.skn-verify-line {\n	border-left-color: var(--skn-mustard);\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	font-family: ui-monospace, SFMono-Regular, Consolas, monospace;\n	letter-spacing: 0.02em;\n}\n\n.skn-verify-line::before {\n	content: \"✓ \";\n	color: var(--skn-mustard);\n}\n\n/* ---------------------------------------------------------\n   Single posts\n   --------------------------------------------------------- */\n\n.single .entry-header .post-thumbnail {\n	display: none !important;\n}\n\n.single .entry-content p {\n	font-size: 18px;\n	line-height: 1.85;\n}\n\n.skn-post-image {\n	margin: 36px 0 !important;\n}\n\n.skn-post-image img {\n	border-radius: 16px;\n	box-shadow: 0 20px 50px rgba(18, 59, 50, 0.15);\n}\n\n.skn-schedule-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-mustard);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-weight: 700;\n	color: var(--skn-green) !important;\n	margin-top: 28px !important;\n}\n\n.single .entry-footer {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 24px 32px 0 !important;\n	border-top: 1px solid var(--skn-line);\n	font-size: 13px;\n	color: var(--skn-muted);\n}\n\n.single .entry-footer .posted-by {\n	margin-bottom: 8px;\n}\n\n.single .entry-footer .post-taxonomies {\n	margin-top: 8px;\n}\n\n.single .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n.single .author-bio {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 0 32px !important;\n}\n\n/* ---------------------------------------------------------\n   Blog & archives\n   --------------------------------------------------------- */\n\n.blog .site-main,\n.archive .site-main {\n	max-width: 1100px !important;\n	margin: 0 auto !important;\n	padding: 0 32px 80px !important;\n}\n\n.blog .page-header,\n.archive .page-header {\n	max-width: 100% !important;\n	margin: 56px 0 32px !important;\n	padding: 0 !important;\n}\n\n.blog .page-title,\n.archive .page-title {\n	font-size: clamp(36px, 4.5vw, 56px) !important;\n	margin: 0 !important;\n}\n\n.archive .page-header .archive-description,\n.archive .page-header .archive-description p {\n	font-family: var(--skn-sans) !important;\n	font-size: 17px !important;\n	line-height: 1.7 !important;\n	color: var(--skn-muted) !important;\n	max-width: 720px;\n	margin: 12px 0 0 !important;\n}\n\n.blog article,\n.archive article {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 24px !important;\n	margin-bottom: 24px;\n	display: grid;\n	grid-template-columns: 200px 1fr;\n	grid-template-rows: auto auto auto;\n	gap: 0 28px;\n	align-items: start;\n	align-content: start;\n}\n\n.blog article .entry-header,\n.archive article .entry-header {\n	display: contents;\n}\n\n.blog article .entry-header .post-thumbnail,\n.archive article .entry-header .post-thumbnail {\n	grid-column: 1;\n	grid-row: 1 / span 3;\n	margin: 0 !important;\n}\n\n.blog article .entry-header .post-thumbnail img,\n.archive article .entry-header .post-thumbnail img {\n	border-radius: 12px;\n	width: 100%;\n	height: auto;\n	max-height: 280px;\n	object-fit: cover;\n}\n\n.blog article .entry-header .entry-title,\n.archive article .entry-header .entry-title {\n	grid-column: 2;\n	grid-row: 1;\n	font-size: 28px !important;\n	margin: 0 !important;\n	align-self: start;\n}\n\n.blog article .entry-header .entry-title a,\n.archive article .entry-header .entry-title a {\n	text-decoration: none;\n}\n\n.blog article .entry-header .entry-title a:hover,\n.archive article .entry-header .entry-title a:hover {\n	text-decoration: underline;\n}\n\n.blog article .entry-content,\n.archive article .entry-content {\n	grid-column: 2;\n	grid-row: 2;\n	margin: 8px 0 0 !important;\n	max-width: none !important;\n}\n\n.blog article .entry-content p,\n.archive article .entry-content p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	margin: 0;\n}\n\n.blog article .entry-footer,\n.archive article .entry-footer {\n	grid-column: 2;\n	grid-row: 3;\n	margin: 12px 0 0 !important;\n	padding: 0 !important;\n	border: 0 !important;\n	font-size: 12px;\n	color: var(--skn-muted);\n}\n\n.blog article .entry-footer a,\n.archive article .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n/* ---------------------------------------------------------\n   Footer\n   --------------------------------------------------------- */\n\n.site-footer {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 48px 0 36px !important;\n	background: var(--skn-green-deep);\n	color: var(--skn-cream);\n}\n\n.site-footer > .footer-navigation,\n.site-footer > .site-info {\n	max-width: 1200px;\n	margin-left: auto;\n	margin-right: auto;\n	padding-left: 32px;\n	padding-right: 32px;\n}\n\n.site-footer .footer-navigation {\n	text-align: left;\n	margin: 0 0 20px;\n}\n\n.site-footer .footer-navigation-wrapper {\n	display: flex;\n	justify-content: flex-start !important;\n	gap: 24px;\n	list-style: none;\n	margin: 0;\n	padding: 0;\n}\n\n.site-footer .footer-navigation-wrapper li {\n	line-height: 1.2;\n	margin: 0;\n}\n\n.site-footer .footer-navigation-wrapper li a,\n.site-footer .footer-navigation-wrapper li a:link,\n.site-footer .footer-navigation-wrapper li a:visited,\n.site-footer .footer-navigation-wrapper li a:active {\n	color: rgba(247, 241, 230, 0.72) !important;\n	font-size: 11px;\n	letter-spacing: 0.14em;\n	text-transform: uppercase;\n	text-decoration: none;\n	padding: 6px 0;\n}\n\n.site-footer .footer-navigation-wrapper li a:hover {\n	color: var(--skn-mustard) !important;\n}\n\n.site-footer > .site-info {\n	border-top: 1px solid rgba(247, 241, 230, 0.18);\n	padding-top: 24px;\n	display: flex;\n	align-items: center;\n	justify-content: space-between;\n	gap: 16px;\n}\n\n.site-footer .site-info .site-name {\n	font-family: var(--skn-serif);\n	font-size: 18px;\n}\n\n.site-footer .site-info .site-logo .custom-logo {\n	width: 44px;\n	height: 44px;\n	max-height: 44px;\n}\n\n.site-footer .powered-by,\n.site-footer .privacy-policy {\n	display: none !important;\n}\n\n.site-footer .site-info::after {\n	content: \"Ruang kreasi dan berbagi ide\";\n	font-size: 12px;\n	letter-spacing: 0.08em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.55);\n}\n\n/* ---------------------------------------------------------\n   Responsive\n   --------------------------------------------------------- */\n\n@media (max-width: 1024px) {\n	.skn-hero-title {\n		font-size: clamp(48px, 8vw, 76px) !important;\n	}\n\n	.skn-hero-cols {\n		gap: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 340px);\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 420px;\n	}\n}\n\n@media (max-width: 821px) {\n	.site-header {\n		position: relative;\n		flex-wrap: wrap;\n		padding: 16px 20px !important;\n		gap: 12px;\n	}\n\n	.site-header .custom-logo {\n		width: 44px;\n		height: 44px;\n	}\n\n	.site-title {\n		font-size: 22px !important;\n	}\n\n	.site-description {\n		font-size: 10px !important;\n	}\n\n	.primary-navigation {\n		width: 100%;\n		margin-left: 0;\n	}\n\n	.skn-container {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.skn-hero {\n		padding: 56px 0 64px;\n	}\n\n	.skn-hero-cols {\n		flex-direction: column;\n	}\n\n	.skn-hero-copy {\n		padding-right: 0;\n	}\n\n	.skn-hero-visual {\n		justify-content: flex-start;\n		margin-top: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 320px);\n		transform: rotate(1.5deg);\n	}\n\n	.skn-values {\n		padding: 40px 0;\n	}\n\n	.skn-values-grid .wp-block-column {\n		border-left: 0;\n		border-top: 1px solid var(--skn-line);\n		padding: 20px 0 0;\n		margin-top: 20px;\n	}\n\n	.skn-values-grid .wp-block-column:first-child {\n		border-top: 0;\n		margin-top: 0;\n		padding-top: 0;\n	}\n\n	.skn-programs,\n	.skn-works,\n	.skn-agenda {\n		padding: 64px 0;\n	}\n\n	.skn-card-grid {\n		flex-direction: column;\n	}\n\n	.skn-card-grid .wp-block-column {\n		width: 100%;\n	}\n\n	.skn-works-grid,\n	.skn-agenda-grid {\n		flex-direction: column;\n		gap: 32px;\n	}\n\n	.skn-works-grid .wp-block-column,\n	.skn-agenda-grid .wp-block-column {\n		width: 100% !important;\n		flex-basis: 100% !important;\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 380px;\n	}\n\n	.skn-cta {\n		padding: 64px 0;\n	}\n\n	.page .entry-header,\n	.single .entry-header {\n		margin-top: 32px !important;\n		padding: 0 20px !important;\n	}\n\n	.page .entry-content,\n	.single .entry-content {\n		padding: 0 20px !important;\n		margin-top: 24px !important;\n	}\n\n	.page .entry-title,\n	.single .entry-title {\n		font-size: clamp(34px, 9vw, 48px) !important;\n	}\n\n	.blog .site-main,\n	.archive .site-main {\n		padding: 0 20px 64px !important;\n	}\n\n	.blog article,\n	.archive article {\n		grid-template-columns: 1fr;\n		padding: 20px !important;\n	}\n\n	.blog article .entry-header,\n	.archive article .entry-header {\n		display: block;\n	}\n\n	.blog article .entry-header .post-thumbnail,\n	.archive article .entry-header .post-thumbnail {\n		margin-bottom: 16px !important;\n	}\n\n	.blog article .entry-header .entry-title,\n	.archive article .entry-header .entry-title {\n		font-size: 26px !important;\n	}\n\n	.site-footer > .footer-navigation,\n	.site-footer > .site-info {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.site-footer > .site-info {\n		flex-direction: column;\n		align-items: flex-start;\n	}\n\n	.site-footer .site-info::after {\n		margin-top: 8px;\n	}\n}\n','twentytwentyone','','publish','closed','closed','','twentytwentyone','','','2026-10-27 19:21:04','2026-10-27 11:21:04','',0,'http://localhost:8080/twentytwentyone/',0,'custom_css','',0),
(28,0,'2026-10-27 19:14:25','2026-10-27 11:14:25','/* =========================================================\n   Studio Karya Nusa — custom theme styles\n   Theme: Twenty Twenty-One\n   ========================================================= */\n\n:root {\n	--skn-green: #123b32;\n	--skn-green-deep: #0c2a24;\n	--skn-cream: #f7f1e6;\n	--skn-cream-soft: #fbf7ef;\n	--skn-terra: #d97757;\n	--skn-mustard: #e3b23c;\n	--skn-ink: #1f2421;\n	--skn-muted: #5e6a63;\n	--skn-line: rgba(18, 59, 50, 0.16);\n	--skn-serif: Georgia, \"Times New Roman\", serif;\n	--skn-sans: \"Segoe UI\", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;\n\n	--global--color-primary: var(--skn-green);\n	--global--color-primary-hover: var(--skn-terra);\n	--global--color-background: var(--skn-cream);\n	--global--color-secondary: var(--skn-terra);\n	--global--color-border: var(--skn-line);\n	--global--font-primary: var(--skn-serif);\n	--global--font-secondary: var(--skn-sans);\n	--branding--title--font-family: var(--skn-serif);\n	--branding--description--font-family: var(--skn-sans);\n	--entry-header--font-family: var(--skn-serif);\n	--footer--color-text: var(--skn-cream);\n}\n\nhtml {\n	scroll-behavior: smooth;\n}\n\nbody {\n	background: var(--skn-cream);\n	color: var(--skn-ink);\n	font-family: var(--skn-sans);\n	font-size: 17px;\n	line-height: 1.75;\n	-webkit-font-smoothing: antialiased;\n}\n\n::selection {\n	background: var(--skn-terra);\n	color: var(--skn-cream);\n}\n\nh1, h2, h3, h4, h5, h6,\n.site-title,\n.entry-title,\n.page-title {\n	font-family: var(--skn-serif);\n	color: var(--skn-green);\n	line-height: 1.08;\n	letter-spacing: -0.02em;\n}\n\na {\n	color: var(--skn-green);\n	text-decoration-thickness: 1px;\n	text-underline-offset: 3px;\n}\n\na:hover,\na:focus {\n	color: var(--skn-terra);\n}\n\n/* ---------------------------------------------------------\n   Header\n   --------------------------------------------------------- */\n\n.site-header {\n	max-width: 1240px !important;\n	margin: 0 auto !important;\n	padding: 22px 32px !important;\n	display: flex !important;\n	align-items: center;\n	gap: 18px;\n	position: sticky;\n	top: 0;\n	z-index: 100;\n	background: rgba(247, 241, 230, 0.96);\n	backdrop-filter: blur(12px);\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.site-header > .site-logo {\n	width: auto !important;\n	padding: 0 !important;\n	border: 0 !important;\n	margin: 0 !important;\n	flex: 0 0 auto;\n}\n\n.site-header .custom-logo {\n	width: 54px;\n	height: 54px;\n	max-height: 54px;\n	max-width: 54px;\n	object-fit: contain;\n	border-radius: 50%;\n}\n\n.site-branding {\n	margin: 0 !important;\n	flex: 1 1 auto;\n	min-width: 0;\n}\n\n.site-title {\n	font-size: 26px !important;\n	line-height: 1.05 !important;\n	margin: 0 !important;\n	letter-spacing: -0.02em;\n}\n\n.site-title a {\n	color: var(--skn-green) !important;\n	text-decoration: none;\n}\n\n.site-description {\n	margin: 5px 0 0 !important;\n	font-size: 11px !important;\n	letter-spacing: 0.16em;\n	text-transform: uppercase;\n	color: var(--skn-muted) !important;\n	line-height: 1.4;\n}\n\n.primary-navigation {\n	margin-left: auto;\n}\n\n@media only screen and (min-width: 822px) {\n	#primary-menu-list {\n		display: flex;\n		align-items: center;\n		gap: 28px;\n		margin: 0;\n		padding: 0;\n		list-style: none;\n	}\n\n	#primary-menu-list li {\n		margin: 0;\n	}\n\n	#primary-menu-list a {\n		font-size: 12px;\n		font-weight: 600;\n		letter-spacing: 0.12em;\n		text-transform: uppercase;\n		text-decoration: none;\n		color: var(--skn-green);\n		padding: 6px 0;\n		position: relative;\n	}\n\n	#primary-menu-list a::after {\n		content: \"\";\n		position: absolute;\n		left: 0;\n		right: 0;\n		bottom: 0;\n		height: 2px;\n		background: var(--skn-terra);\n		transform: scaleX(0);\n		transform-origin: left;\n		transition: transform 0.2s ease;\n	}\n\n	#primary-menu-list a:hover::after,\n	#primary-menu-list .current-menu-item > a::after {\n		transform: scaleX(1);\n	}\n\n	#primary-menu-list .current-menu-item > a {\n		color: var(--skn-terra);\n	}\n\n	.menu-button-container {\n		display: none;\n	}\n}\n\n/* ---------------------------------------------------------\n   Home layout\n   --------------------------------------------------------- */\n\nbody.home .site-content {\n	padding: 0 !important;\n}\n\nbody.home .content-area,\nbody.home .site-main {\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\nbody.home .entry-content .wp-block-group__inner-container > *,\nbody.home .entry-content .wp-block-columns,\nbody.home .entry-content .wp-block-column,\nbody.home .entry-content .wp-block-latest-posts {\n	max-width: none !important;\n}\n\n.skn-container {\n	max-width: 1200px !important;\n	margin-left: auto !important;\n	margin-right: auto !important;\n	padding-left: 32px;\n	padding-right: 32px;\n	box-sizing: border-box;\n}\n\n.skn-container > .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Hero\n   --------------------------------------------------------- */\n\n.skn-hero {\n	background:\n		radial-gradient(circle at 82% 18%, rgba(227, 178, 60, 0.18), transparent 32%),\n		radial-gradient(circle at 12% 88%, rgba(217, 119, 87, 0.16), transparent 36%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green) 60%, #1b4d42);\n	color: var(--skn-cream);\n	padding: 92px 0 96px;\n	position: relative;\n	overflow: hidden;\n}\n\n.skn-hero::before {\n	content: \"\";\n	position: absolute;\n	inset: 0;\n	background-image: radial-gradient(rgba(247, 241, 230, 0.08) 1px, transparent 1px);\n	background-size: 26px 26px;\n	opacity: 0.35;\n	pointer-events: none;\n}\n\n.skn-hero-inner {\n	position: relative;\n	z-index: 1;\n}\n\n.skn-hero-cols {\n	align-items: center;\n	gap: 48px;\n}\n\n.skn-hero-copy {\n	padding-right: 20px;\n}\n\n.skn-hero-kicker {\n	font-size: 11px;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-mustard);\n	margin: 0 0 18px;\n	font-weight: 700;\n}\n\n.skn-hero-title {\n	font-size: clamp(56px, 7vw, 104px) !important;\n	line-height: 0.92 !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 22px !important;\n	letter-spacing: -0.045em !important;\n}\n\n.skn-hero-tagline {\n	font-family: var(--skn-serif);\n	font-size: clamp(22px, 2.4vw, 32px);\n	font-style: italic;\n	color: var(--skn-cream) !important;\n	margin: 0 0 18px;\n	line-height: 1.2;\n}\n\n.skn-hero-text {\n	font-size: 17px;\n	line-height: 1.75;\n	color: rgba(247, 241, 230, 0.78);\n	max-width: 520px;\n	margin: 0 0 32px;\n}\n\n.skn-hero-buttons {\n	gap: 14px;\n}\n\n.skn-btn .wp-block-button__link {\n	border-radius: 999px;\n	padding: 14px 26px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease;\n}\n\n.skn-btn-primary .wp-block-button__link {\n	background: var(--skn-terra);\n	color: var(--skn-cream);\n}\n\n.skn-btn-primary .wp-block-button__link:hover {\n	background: var(--skn-mustard);\n	color: var(--skn-green-deep);\n	transform: translateY(-2px);\n}\n\n.skn-btn-ghost .wp-block-button__link {\n	background: transparent;\n	color: var(--skn-cream);\n	border: 1px solid rgba(247, 241, 230, 0.45);\n}\n\n.skn-btn-ghost .wp-block-button__link:hover {\n	background: var(--skn-cream);\n	color: var(--skn-green);\n	transform: translateY(-2px);\n}\n\n.skn-hero-visual {\n	display: flex;\n	justify-content: flex-end;\n}\n\n.skn-hero-poster {\n	margin: 0 !important;\n	width: min(100%, 420px);\n	transform: rotate(2.5deg);\n}\n\n.skn-hero-poster img {\n	width: 100%;\n	height: auto;\n	border: 10px solid var(--skn-cream);\n	border-radius: 6px;\n	box-shadow: 0 30px 70px rgba(0, 0, 0, 0.35);\n	display: block;\n}\n\n/* ---------------------------------------------------------\n   Values\n   --------------------------------------------------------- */\n\n.skn-values {\n	background: var(--skn-cream);\n	padding: 64px 0 56px;\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.skn-values-grid {\n	gap: 0;\n}\n\n.skn-values-grid .wp-block-column {\n	padding: 0 28px;\n	border-left: 1px solid var(--skn-line);\n}\n\n.skn-values-grid .wp-block-column:first-child {\n	border-left: 0;\n	padding-left: 0;\n}\n\n.skn-value-num {\n	font-family: var(--skn-serif);\n	font-size: 14px;\n	color: var(--skn-terra);\n	letter-spacing: 0.1em;\n	margin: 0 0 10px;\n}\n\n.skn-value-title {\n	font-size: 30px !important;\n	margin: 0 0 8px !important;\n}\n\n.skn-values p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0;\n	line-height: 1.65;\n}\n\n/* ---------------------------------------------------------\n   Programs\n   --------------------------------------------------------- */\n\n.skn-programs {\n	background: var(--skn-cream-soft);\n	padding: 96px 0;\n}\n\n.skn-section-head {\n	max-width: 720px !important;\n	margin: 0 0 44px !important;\n}\n\n.skn-kicker {\n	font-size: 11px;\n	font-weight: 700;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-terra);\n	margin: 0 0 12px;\n}\n\n.skn-section-title {\n	font-size: clamp(36px, 4vw, 56px) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-section-lead {\n	font-size: 17px;\n	color: var(--skn-muted);\n	line-height: 1.7;\n	margin: 0;\n	max-width: 620px;\n}\n\n.skn-card-grid {\n	gap: 24px;\n	align-items: stretch;\n}\n\n.skn-card-grid .wp-block-column {\n	display: flex;\n}\n\n.skn-card {\n	background: var(--skn-cream);\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 30px 28px 26px !important;\n	width: 100%;\n	display: flex;\n	flex-direction: column;\n	transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;\n}\n\n.skn-card:hover {\n	transform: translateY(-6px);\n	box-shadow: 0 18px 40px rgba(18, 59, 50, 0.1);\n	border-color: rgba(217, 119, 87, 0.45);\n}\n\n.skn-card-num {\n	font-family: var(--skn-serif);\n	font-size: 13px;\n	letter-spacing: 0.12em;\n	color: var(--skn-terra);\n	margin: 0 0 22px;\n}\n\n.skn-card h3 {\n	font-size: 25px !important;\n	margin: 0 0 10px !important;\n	line-height: 1.15 !important;\n}\n\n.skn-card p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0 0 18px;\n	line-height: 1.65;\n}\n\n.skn-card-link {\n	margin-top: auto !important;\n}\n\n.skn-card-link a,\n.skn-section-link a {\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.1em;\n	text-transform: uppercase;\n	text-decoration: none;\n	color: var(--skn-terra);\n	border-bottom: 1px solid rgba(217, 119, 87, 0.4);\n	padding-bottom: 2px;\n}\n\n.skn-card-link a:hover,\n.skn-section-link a:hover {\n	color: var(--skn-green);\n	border-color: var(--skn-green);\n}\n\n/* ---------------------------------------------------------\n   Works\n   --------------------------------------------------------- */\n\n.skn-works {\n	background: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-works-grid {\n	gap: 56px;\n}\n\n.skn-works .skn-section-title {\n	font-size: clamp(34px, 4vw, 52px) !important;\n}\n\n.skn-latest {\n	display: block !important;\n	margin: 0 !important;\n	padding: 0 !important;\n	list-style: none !important;\n}\n\n.skn-latest li {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 20px;\n	overflow: hidden;\n	padding: 0 !important;\n	margin: 0 !important;\n	box-shadow: 0 18px 50px rgba(18, 59, 50, 0.08);\n	display: grid;\n	grid-template-columns: 42% 1fr;\n	align-items: stretch;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image {\n	margin: 0 !important;\n	grid-row: 1 / span 2;\n	background: var(--skn-green);\n	padding: 18px;\n	display: flex;\n	align-items: center;\n	justify-content: center;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image img {\n	width: 100% !important;\n	height: auto !important;\n	max-height: 420px;\n	object-fit: contain;\n	display: block;\n	box-shadow: 0 14px 30px rgba(0, 0, 0, 0.28);\n}\n\n.skn-latest .wp-block-latest-posts__post-title {\n	display: block;\n	font-family: var(--skn-serif);\n	font-size: 30px;\n	line-height: 1.15;\n	color: var(--skn-green);\n	text-decoration: none;\n	padding: 28px 30px 0;\n}\n\n.skn-latest .wp-block-latest-posts__post-title:hover {\n	color: var(--skn-terra);\n}\n\n.skn-latest .wp-block-latest-posts__post-excerpt {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	padding: 10px 30px 28px;\n	margin: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Agenda\n   --------------------------------------------------------- */\n\n.skn-agenda {\n	background:\n		radial-gradient(circle at 90% 10%, rgba(227, 178, 60, 0.16), transparent 30%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green));\n	color: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-agenda .skn-section-title {\n	color: var(--skn-cream) !important;\n}\n\n.skn-agenda .skn-kicker {\n	color: var(--skn-mustard);\n}\n\n.skn-agenda .skn-section-lead {\n	color: rgba(247, 241, 230, 0.75);\n}\n\n.skn-agenda .skn-section-link a {\n	color: var(--skn-mustard);\n	border-color: rgba(227, 178, 60, 0.5);\n}\n\n.skn-agenda .skn-section-link a:hover {\n	color: var(--skn-cream);\n	border-color: var(--skn-cream);\n}\n\n.skn-latest-agenda li {\n	background: #fffaf2;\n}\n\n/* ---------------------------------------------------------\n   CTA\n   --------------------------------------------------------- */\n\n.skn-cta {\n	background:\n		radial-gradient(circle at 15% 20%, rgba(247, 241, 230, 0.12), transparent 30%),\n		var(--skn-terra);\n	color: var(--skn-cream);\n	padding: 88px 0;\n	text-align: center;\n}\n\n.skn-cta-inner {\n	max-width: 820px !important;\n}\n\n.skn-cta .skn-kicker {\n	color: var(--skn-green-deep);\n}\n\n.skn-cta-title {\n	font-size: clamp(40px, 5vw, 64px) !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-cta-text {\n	font-size: 18px;\n	color: rgba(247, 241, 230, 0.85);\n	max-width: 620px;\n	margin: 0 auto 28px;\n}\n\n.skn-cta-actions {\n	margin: 0 0 24px !important;\n}\n\n.skn-cta-button {\n	display: inline-block;\n	background: var(--skn-cream);\n	color: var(--skn-green) !important;\n	border-radius: 999px;\n	padding: 14px 30px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease;\n}\n\n.skn-cta-button:hover {\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	transform: translateY(-2px);\n}\n\n.skn-cta-location {\n	font-size: 11px;\n	letter-spacing: 0.18em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.65);\n	margin: 0;\n}\n\n/* ---------------------------------------------------------\n   Required pages\n   --------------------------------------------------------- */\n\n.page .site-main,\n.single .site-main {\n	padding-top: 0;\n}\n\n.page .entry-header,\n.single .entry-header {\n	max-width: 900px !important;\n	margin: 56px auto 0 !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-title,\n.single .entry-title {\n	font-size: clamp(42px, 6vw, 72px) !important;\n	line-height: 0.98 !important;\n	margin: 0 !important;\n	color: var(--skn-green);\n}\n\n.page .entry-content,\n.single .entry-content {\n	max-width: 760px !important;\n	margin: 32px auto 72px !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-content > *,\n.single .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.page .entry-content .wp-block-group__inner-container > *,\n.single .entry-content .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.skn-required-page {\n	position: relative;\n}\n\n.skn-page-heading {\n	font-size: clamp(34px, 4.5vw, 52px) !important;\n	margin: 0 0 18px !important;\n}\n\n.skn-lead {\n	font-size: 20px !important;\n	line-height: 1.7 !important;\n	color: var(--skn-ink) !important;\n}\n\n.skn-note-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-terra);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-size: 16px !important;\n	font-weight: 600;\n	color: var(--skn-green) !important;\n	margin: 28px 0 0 !important;\n}\n\n.skn-verify-line {\n	border-left-color: var(--skn-mustard);\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	font-family: ui-monospace, SFMono-Regular, Consolas, monospace;\n	letter-spacing: 0.02em;\n}\n\n.skn-verify-line::before {\n	content: \"✓ \";\n	color: var(--skn-mustard);\n}\n\n/* ---------------------------------------------------------\n   Single posts\n   --------------------------------------------------------- */\n\n.single .entry-header .post-thumbnail {\n	display: none !important;\n}\n\n.single .entry-content p {\n	font-size: 18px;\n	line-height: 1.85;\n}\n\n.skn-post-image {\n	margin: 36px 0 !important;\n}\n\n.skn-post-image img {\n	border-radius: 16px;\n	box-shadow: 0 20px 50px rgba(18, 59, 50, 0.15);\n}\n\n.skn-schedule-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-mustard);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-weight: 700;\n	color: var(--skn-green) !important;\n	margin-top: 28px !important;\n}\n\n.single .entry-footer {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 24px 32px 0 !important;\n	border-top: 1px solid var(--skn-line);\n	font-size: 13px;\n	color: var(--skn-muted);\n}\n\n.single .entry-footer .posted-by {\n	margin-bottom: 8px;\n}\n\n.single .entry-footer .post-taxonomies {\n	margin-top: 8px;\n}\n\n.single .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n.single .author-bio {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 0 32px !important;\n}\n\n/* ---------------------------------------------------------\n   Blog & archives\n   --------------------------------------------------------- */\n\n.blog .site-main,\n.archive .site-main {\n	max-width: 1100px !important;\n	margin: 0 auto !important;\n	padding: 0 32px 80px !important;\n}\n\n.blog .page-header,\n.archive .page-header {\n	max-width: 100% !important;\n	margin: 56px 0 32px !important;\n	padding: 0 !important;\n}\n\n.blog .page-title,\n.archive .page-title {\n	font-size: clamp(40px, 5vw, 64px) !important;\n	margin: 0 !important;\n}\n\n.blog article,\n.archive article {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 28px !important;\n	margin-bottom: 24px;\n	display: grid;\n	grid-template-columns: 240px 1fr;\n	grid-template-rows: auto auto auto;\n	gap: 0 28px;\n	align-items: center;\n}\n\n.blog article .entry-header,\n.archive article .entry-header {\n	display: contents;\n}\n\n.blog article .entry-header .post-thumbnail,\n.archive article .entry-header .post-thumbnail {\n	grid-column: 1;\n	grid-row: 1 / span 3;\n	margin: 0 !important;\n}\n\n.blog article .entry-header .post-thumbnail img,\n.archive article .entry-header .post-thumbnail img {\n	border-radius: 12px;\n	width: 100%;\n	height: 100%;\n	object-fit: cover;\n}\n\n.blog article .entry-header .entry-title,\n.archive article .entry-header .entry-title {\n	grid-column: 2;\n	grid-row: 1;\n	font-size: 30px !important;\n	margin: 0 !important;\n}\n\n.blog article .entry-content,\n.archive article .entry-content {\n	grid-column: 2;\n	grid-row: 2;\n	margin: 8px 0 0 !important;\n	max-width: none !important;\n}\n\n.blog article .entry-content p,\n.archive article .entry-content p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	margin: 0;\n}\n\n.blog article .entry-footer,\n.archive article .entry-footer {\n	grid-column: 2;\n	grid-row: 3;\n	margin: 8px 0 0 !important;\n	padding: 0 !important;\n	border: 0 !important;\n}\n\n.blog article .entry-footer a,\n.archive article .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n/* ---------------------------------------------------------\n   Footer\n   --------------------------------------------------------- */\n\n.site-footer {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 48px 0 36px !important;\n	background: var(--skn-green-deep);\n	color: var(--skn-cream);\n}\n\n.site-footer > .footer-navigation,\n.site-footer > .site-info {\n	max-width: 1200px;\n	margin-left: auto;\n	margin-right: auto;\n	padding-left: 32px;\n	padding-right: 32px;\n}\n\n.site-footer .footer-navigation-wrapper {\n	display: flex;\n	gap: 24px;\n	list-style: none;\n	margin: 0 0 24px;\n	padding: 0;\n}\n\n.site-footer .footer-navigation-wrapper a {\n	color: rgba(247, 241, 230, 0.7);\n	font-size: 11px;\n	letter-spacing: 0.14em;\n	text-transform: uppercase;\n	text-decoration: none;\n}\n\n.site-footer .footer-navigation-wrapper a:hover {\n	color: var(--skn-mustard);\n}\n\n.site-footer > .site-info {\n	border-top: 1px solid rgba(247, 241, 230, 0.18);\n	padding-top: 24px;\n	display: flex;\n	align-items: center;\n	justify-content: space-between;\n	gap: 16px;\n}\n\n.site-footer .site-info .site-name {\n	font-family: var(--skn-serif);\n	font-size: 18px;\n}\n\n.site-footer .site-info .site-logo .custom-logo {\n	width: 44px;\n	height: 44px;\n	max-height: 44px;\n}\n\n.site-footer .powered-by,\n.site-footer .privacy-policy {\n	display: none !important;\n}\n\n.site-footer .site-info::after {\n	content: \"Ruang kreasi dan berbagi ide\";\n	font-size: 12px;\n	letter-spacing: 0.08em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.55);\n}\n\n/* ---------------------------------------------------------\n   Responsive\n   --------------------------------------------------------- */\n\n@media (max-width: 1024px) {\n	.skn-hero-title {\n		font-size: clamp(48px, 8vw, 76px) !important;\n	}\n\n	.skn-hero-cols {\n		gap: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 340px);\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 420px;\n	}\n}\n\n@media (max-width: 821px) {\n	.site-header {\n		position: relative;\n		flex-wrap: wrap;\n		padding: 16px 20px !important;\n		gap: 12px;\n	}\n\n	.site-header .custom-logo {\n		width: 44px;\n		height: 44px;\n	}\n\n	.site-title {\n		font-size: 22px !important;\n	}\n\n	.site-description {\n		font-size: 10px !important;\n	}\n\n	.primary-navigation {\n		width: 100%;\n		margin-left: 0;\n	}\n\n	.skn-container {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.skn-hero {\n		padding: 56px 0 64px;\n	}\n\n	.skn-hero-cols {\n		flex-direction: column;\n	}\n\n	.skn-hero-copy {\n		padding-right: 0;\n	}\n\n	.skn-hero-visual {\n		justify-content: flex-start;\n		margin-top: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 320px);\n		transform: rotate(1.5deg);\n	}\n\n	.skn-values {\n		padding: 40px 0;\n	}\n\n	.skn-values-grid .wp-block-column {\n		border-left: 0;\n		border-top: 1px solid var(--skn-line);\n		padding: 20px 0 0;\n		margin-top: 20px;\n	}\n\n	.skn-values-grid .wp-block-column:first-child {\n		border-top: 0;\n		margin-top: 0;\n		padding-top: 0;\n	}\n\n	.skn-programs,\n	.skn-works,\n	.skn-agenda {\n		padding: 64px 0;\n	}\n\n	.skn-card-grid {\n		flex-direction: column;\n	}\n\n	.skn-card-grid .wp-block-column {\n		width: 100%;\n	}\n\n	.skn-works-grid,\n	.skn-agenda-grid {\n		flex-direction: column;\n		gap: 32px;\n	}\n\n	.skn-works-grid .wp-block-column,\n	.skn-agenda-grid .wp-block-column {\n		width: 100% !important;\n		flex-basis: 100% !important;\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 380px;\n	}\n\n	.skn-cta {\n		padding: 64px 0;\n	}\n\n	.page .entry-header,\n	.single .entry-header {\n		margin-top: 32px !important;\n		padding: 0 20px !important;\n	}\n\n	.page .entry-content,\n	.single .entry-content {\n		padding: 0 20px !important;\n		margin-top: 24px !important;\n	}\n\n	.page .entry-title,\n	.single .entry-title {\n		font-size: clamp(34px, 9vw, 48px) !important;\n	}\n\n	.blog .site-main,\n	.archive .site-main {\n		padding: 0 20px 64px !important;\n	}\n\n	.blog article,\n	.archive article {\n		grid-template-columns: 1fr;\n		padding: 20px !important;\n	}\n\n	.blog article .entry-header,\n	.archive article .entry-header {\n		display: block;\n	}\n\n	.blog article .entry-header .post-thumbnail,\n	.archive article .entry-header .post-thumbnail {\n		margin-bottom: 16px !important;\n	}\n\n	.blog article .entry-header .entry-title,\n	.archive article .entry-header .entry-title {\n		font-size: 26px !important;\n	}\n\n	.site-footer > .footer-navigation,\n	.site-footer > .site-info {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.site-footer > .site-info {\n		flex-direction: column;\n		align-items: flex-start;\n	}\n\n	.site-footer .site-info::after {\n		margin-top: 8px;\n	}\n}\n','twentytwentyone','','inherit','closed','closed','','27-revision-v1','','','2026-10-27 19:14:25','2026-10-27 11:14:25','',27,'http://localhost:8080/?p=28',0,'revision','',0),
(29,0,'2026-10-27 19:18:28','2026-10-27 11:18:28','/* =========================================================\n   Studio Karya Nusa — custom theme styles\n   Theme: Twenty Twenty-One\n   ========================================================= */\n\n:root {\n	--skn-green: #123b32;\n	--skn-green-deep: #0c2a24;\n	--skn-cream: #f7f1e6;\n	--skn-cream-soft: #fbf7ef;\n	--skn-terra: #d97757;\n	--skn-mustard: #e3b23c;\n	--skn-ink: #1f2421;\n	--skn-muted: #5e6a63;\n	--skn-line: rgba(18, 59, 50, 0.16);\n	--skn-serif: Georgia, \"Times New Roman\", serif;\n	--skn-sans: \"Segoe UI\", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;\n\n	--global--color-primary: var(--skn-green);\n	--global--color-primary-hover: var(--skn-terra);\n	--global--color-background: var(--skn-cream);\n	--global--color-secondary: var(--skn-terra);\n	--global--color-border: var(--skn-line);\n	--global--font-primary: var(--skn-serif);\n	--global--font-secondary: var(--skn-sans);\n	--branding--title--font-family: var(--skn-serif);\n	--branding--description--font-family: var(--skn-sans);\n	--entry-header--font-family: var(--skn-serif);\n	--footer--color-text: var(--skn-cream);\n}\n\nhtml {\n	scroll-behavior: smooth;\n}\n\nbody {\n	background: var(--skn-cream);\n	color: var(--skn-ink);\n	font-family: var(--skn-sans);\n	font-size: 17px;\n	line-height: 1.75;\n	-webkit-font-smoothing: antialiased;\n}\n\n::selection {\n	background: var(--skn-terra);\n	color: var(--skn-cream);\n}\n\nh1, h2, h3, h4, h5, h6,\n.site-title,\n.entry-title,\n.page-title {\n	font-family: var(--skn-serif);\n	color: var(--skn-green);\n	line-height: 1.08;\n	letter-spacing: -0.02em;\n}\n\na {\n	color: var(--skn-green);\n	text-decoration-thickness: 1px;\n	text-underline-offset: 3px;\n}\n\na:hover,\na:focus {\n	color: var(--skn-terra);\n}\n\n/* ---------------------------------------------------------\n   Header\n   --------------------------------------------------------- */\n\n.site-header {\n	max-width: 1240px !important;\n	margin: 0 auto !important;\n	padding: 22px 32px !important;\n	display: flex !important;\n	align-items: center;\n	gap: 18px;\n	position: sticky;\n	top: 0;\n	z-index: 100;\n	background: rgba(247, 241, 230, 0.96);\n	backdrop-filter: blur(12px);\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.site-header > .site-logo {\n	width: auto !important;\n	padding: 0 !important;\n	border: 0 !important;\n	margin: 0 !important;\n	flex: 0 0 auto;\n}\n\n.site-header .custom-logo {\n	width: 54px;\n	height: 54px;\n	max-height: 54px;\n	max-width: 54px;\n	object-fit: contain;\n	border-radius: 50%;\n}\n\n.site-branding {\n	margin: 0 !important;\n	flex: 1 1 auto;\n	min-width: 0;\n}\n\n.site-title {\n	font-size: 26px !important;\n	line-height: 1.05 !important;\n	margin: 0 !important;\n	letter-spacing: -0.02em;\n}\n\n.site-title a {\n	color: var(--skn-green) !important;\n	text-decoration: none;\n}\n\n.site-description {\n	margin: 5px 0 0 !important;\n	font-size: 11px !important;\n	letter-spacing: 0.16em;\n	text-transform: uppercase;\n	color: var(--skn-muted) !important;\n	line-height: 1.4;\n}\n\n.primary-navigation {\n	margin-left: auto;\n}\n\n@media only screen and (min-width: 822px) {\n	#primary-menu-list {\n		display: flex;\n		align-items: center;\n		gap: 28px;\n		margin: 0;\n		padding: 0;\n		list-style: none;\n	}\n\n	#primary-menu-list li {\n		margin: 0;\n	}\n\n	#primary-menu-list a {\n		font-size: 12px;\n		font-weight: 600;\n		letter-spacing: 0.12em;\n		text-transform: uppercase;\n		text-decoration: none;\n		color: var(--skn-green);\n		padding: 6px 0;\n		position: relative;\n	}\n\n	#primary-menu-list a::after {\n		content: \"\";\n		position: absolute;\n		left: 0;\n		right: 0;\n		bottom: 0;\n		height: 2px;\n		background: var(--skn-terra);\n		transform: scaleX(0);\n		transform-origin: left;\n		transition: transform 0.2s ease;\n	}\n\n	#primary-menu-list a:hover::after,\n	#primary-menu-list .current-menu-item > a::after {\n		transform: scaleX(1);\n	}\n\n	#primary-menu-list .current-menu-item > a {\n		color: var(--skn-terra);\n	}\n\n	.menu-button-container {\n		display: none;\n	}\n}\n\n/* ---------------------------------------------------------\n   Home layout\n   --------------------------------------------------------- */\n\nbody.home .site-content {\n	padding: 0 !important;\n}\n\nbody.home .content-area,\nbody.home .site-main {\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\nbody.home .entry-content .wp-block-group__inner-container > *,\nbody.home .entry-content .wp-block-columns,\nbody.home .entry-content .wp-block-column,\nbody.home .entry-content .wp-block-latest-posts {\n	max-width: none !important;\n}\n\n.skn-container {\n	max-width: 1200px !important;\n	margin-left: auto !important;\n	margin-right: auto !important;\n	padding-left: 32px;\n	padding-right: 32px;\n	box-sizing: border-box;\n}\n\n.skn-container > .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Hero\n   --------------------------------------------------------- */\n\n.skn-hero {\n	background:\n		radial-gradient(circle at 82% 18%, rgba(227, 178, 60, 0.18), transparent 32%),\n		radial-gradient(circle at 12% 88%, rgba(217, 119, 87, 0.16), transparent 36%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green) 60%, #1b4d42);\n	color: var(--skn-cream);\n	padding: 92px 0 96px;\n	position: relative;\n	overflow: hidden;\n}\n\n.skn-hero::before {\n	content: \"\";\n	position: absolute;\n	inset: 0;\n	background-image: radial-gradient(rgba(247, 241, 230, 0.08) 1px, transparent 1px);\n	background-size: 26px 26px;\n	opacity: 0.35;\n	pointer-events: none;\n}\n\n.skn-hero-inner {\n	position: relative;\n	z-index: 1;\n}\n\n.skn-hero-cols {\n	align-items: center;\n	gap: 48px;\n}\n\n.skn-hero-copy {\n	padding-right: 20px;\n}\n\n.skn-hero-kicker {\n	font-size: 11px;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-mustard);\n	margin: 0 0 18px;\n	font-weight: 700;\n}\n\n.skn-hero-title {\n	font-size: clamp(56px, 7vw, 104px) !important;\n	line-height: 0.92 !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 22px !important;\n	letter-spacing: -0.045em !important;\n}\n\n.skn-hero-tagline {\n	font-family: var(--skn-serif);\n	font-size: clamp(22px, 2.4vw, 32px);\n	font-style: italic;\n	color: var(--skn-cream) !important;\n	margin: 0 0 18px;\n	line-height: 1.2;\n}\n\n.skn-hero-text {\n	font-size: 17px;\n	line-height: 1.75;\n	color: rgba(247, 241, 230, 0.78);\n	max-width: 520px;\n	margin: 0 0 32px;\n}\n\n.skn-hero-buttons {\n	gap: 14px;\n}\n\n.skn-btn .wp-block-button__link {\n	border-radius: 999px;\n	padding: 14px 26px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease;\n}\n\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link,\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link:not(:hover):not(:active) {\n	background-color: var(--skn-terra) !important;\n	color: var(--skn-cream) !important;\n	border-color: var(--skn-terra) !important;\n}\n\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link:hover {\n	background-color: var(--skn-mustard) !important;\n	color: var(--skn-green-deep) !important;\n	border-color: var(--skn-mustard) !important;\n	transform: translateY(-2px);\n}\n\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link,\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:not(:hover):not(:active) {\n	background-color: transparent !important;\n	color: var(--skn-cream) !important;\n	border-color: rgba(247, 241, 230, 0.45) !important;\n}\n\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:hover {\n	background-color: var(--skn-cream) !important;\n	color: var(--skn-green) !important;\n	border-color: var(--skn-cream) !important;\n	transform: translateY(-2px);\n}\n\n.skn-hero-visual {\n	display: flex;\n	justify-content: flex-end;\n}\n\n.skn-hero-poster {\n	margin: 0 !important;\n	width: min(100%, 420px);\n	transform: rotate(2.5deg);\n}\n\n.skn-hero-poster img {\n	width: 100%;\n	height: auto;\n	border: 10px solid var(--skn-cream);\n	border-radius: 6px;\n	box-shadow: 0 30px 70px rgba(0, 0, 0, 0.35);\n	display: block;\n}\n\n/* ---------------------------------------------------------\n   Values\n   --------------------------------------------------------- */\n\n.skn-values {\n	background: var(--skn-cream);\n	padding: 64px 0 56px;\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.skn-values-grid {\n	gap: 0;\n}\n\n.skn-values-grid .wp-block-column {\n	padding: 0 28px;\n	border-left: 1px solid var(--skn-line);\n}\n\n.skn-values-grid .wp-block-column:first-child {\n	border-left: 0;\n	padding-left: 0;\n}\n\n.skn-value-num {\n	font-family: var(--skn-serif);\n	font-size: 14px;\n	color: var(--skn-terra);\n	letter-spacing: 0.1em;\n	margin: 0 0 10px;\n}\n\n.skn-value-title {\n	font-size: 30px !important;\n	margin: 0 0 8px !important;\n}\n\n.skn-values p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0;\n	line-height: 1.65;\n}\n\n/* ---------------------------------------------------------\n   Programs\n   --------------------------------------------------------- */\n\n.skn-programs {\n	background: var(--skn-cream-soft);\n	padding: 96px 0;\n}\n\n.skn-section-head {\n	max-width: 720px !important;\n	margin: 0 0 44px !important;\n}\n\n.skn-kicker {\n	font-size: 11px;\n	font-weight: 700;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-terra);\n	margin: 0 0 12px;\n}\n\n.skn-section-title {\n	font-size: clamp(36px, 4vw, 56px) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-section-lead {\n	font-size: 17px;\n	color: var(--skn-muted);\n	line-height: 1.7;\n	margin: 0;\n	max-width: 620px;\n}\n\n.skn-card-grid {\n	gap: 24px;\n	align-items: stretch;\n}\n\n.skn-card-grid .wp-block-column {\n	display: flex;\n}\n\n.skn-card {\n	background: var(--skn-cream);\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 30px 28px 26px !important;\n	width: 100%;\n	display: flex;\n	flex-direction: column;\n	transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;\n}\n\n.skn-card:hover {\n	transform: translateY(-6px);\n	box-shadow: 0 18px 40px rgba(18, 59, 50, 0.1);\n	border-color: rgba(217, 119, 87, 0.45);\n}\n\n.skn-card-num {\n	font-family: var(--skn-serif);\n	font-size: 13px;\n	letter-spacing: 0.12em;\n	color: var(--skn-terra);\n	margin: 0 0 22px;\n}\n\n.skn-card h3 {\n	font-size: 25px !important;\n	margin: 0 0 10px !important;\n	line-height: 1.15 !important;\n}\n\n.skn-card p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0 0 18px;\n	line-height: 1.65;\n}\n\n.skn-card-link {\n	margin-top: auto !important;\n}\n\n.skn-card-link a,\n.skn-section-link a {\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.1em;\n	text-transform: uppercase;\n	text-decoration: none;\n	color: var(--skn-terra);\n	border-bottom: 1px solid rgba(217, 119, 87, 0.4);\n	padding-bottom: 2px;\n}\n\n.skn-card-link a:hover,\n.skn-section-link a:hover {\n	color: var(--skn-green);\n	border-color: var(--skn-green);\n}\n\n/* ---------------------------------------------------------\n   Works\n   --------------------------------------------------------- */\n\n.skn-works {\n	background: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-works-grid {\n	gap: 56px;\n}\n\n.skn-works .skn-section-title {\n	font-size: clamp(34px, 4vw, 52px) !important;\n}\n\n.skn-latest {\n	display: block !important;\n	margin: 0 !important;\n	padding: 0 !important;\n	list-style: none !important;\n}\n\n.skn-latest li {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 20px;\n	overflow: hidden;\n	padding: 0 !important;\n	margin: 0 !important;\n	box-shadow: 0 18px 50px rgba(18, 59, 50, 0.08);\n	display: grid;\n	grid-template-columns: 42% 1fr;\n	align-items: stretch;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image {\n	margin: 0 !important;\n	grid-row: 1 / span 2;\n	background: var(--skn-green);\n	padding: 18px;\n	display: flex;\n	align-items: center;\n	justify-content: center;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image img {\n	width: 100% !important;\n	height: auto !important;\n	max-height: 420px;\n	object-fit: contain;\n	display: block;\n	box-shadow: 0 14px 30px rgba(0, 0, 0, 0.28);\n}\n\n.skn-latest .wp-block-latest-posts__post-title {\n	display: block;\n	font-family: var(--skn-serif);\n	font-size: 30px;\n	line-height: 1.15;\n	color: var(--skn-green);\n	text-decoration: none;\n	padding: 28px 30px 0;\n}\n\n.skn-latest .wp-block-latest-posts__post-title:hover {\n	color: var(--skn-terra);\n}\n\n.skn-latest .wp-block-latest-posts__post-excerpt {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	padding: 10px 30px 28px;\n	margin: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Agenda\n   --------------------------------------------------------- */\n\n.skn-agenda {\n	background:\n		radial-gradient(circle at 90% 10%, rgba(227, 178, 60, 0.16), transparent 30%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green));\n	color: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-agenda .skn-section-title {\n	color: var(--skn-cream) !important;\n}\n\n.skn-agenda .skn-kicker {\n	color: var(--skn-mustard);\n}\n\n.skn-agenda .skn-section-lead {\n	color: rgba(247, 241, 230, 0.75);\n}\n\n.skn-agenda .skn-section-link a {\n	color: var(--skn-mustard);\n	border-color: rgba(227, 178, 60, 0.5);\n}\n\n.skn-agenda .skn-section-link a:hover {\n	color: var(--skn-cream);\n	border-color: var(--skn-cream);\n}\n\n.skn-latest-agenda li {\n	background: #fffaf2;\n}\n\n/* ---------------------------------------------------------\n   CTA\n   --------------------------------------------------------- */\n\n.skn-cta {\n	background:\n		radial-gradient(circle at 15% 20%, rgba(247, 241, 230, 0.12), transparent 30%),\n		var(--skn-terra);\n	color: var(--skn-cream);\n	padding: 88px 0;\n	text-align: center;\n}\n\n.skn-cta-inner {\n	max-width: 820px !important;\n}\n\n.skn-cta .skn-kicker {\n	color: var(--skn-green-deep);\n}\n\n.skn-cta-title {\n	font-size: clamp(40px, 5vw, 64px) !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-cta-text {\n	font-size: 18px;\n	color: rgba(247, 241, 230, 0.85);\n	max-width: 620px;\n	margin: 0 auto 28px;\n}\n\n.skn-cta-actions {\n	margin: 0 0 24px !important;\n}\n\n.skn-cta-button {\n	display: inline-block;\n	background: var(--skn-cream);\n	color: var(--skn-green) !important;\n	border-radius: 999px;\n	padding: 14px 30px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease;\n}\n\n.skn-cta-button:hover {\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	transform: translateY(-2px);\n}\n\n.skn-cta-location {\n	font-size: 11px;\n	letter-spacing: 0.18em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.65);\n	margin: 0;\n}\n\n/* ---------------------------------------------------------\n   Required pages\n   --------------------------------------------------------- */\n\n.page .site-main,\n.single .site-main {\n	padding-top: 0;\n}\n\n.page .entry-header,\n.single .entry-header {\n	max-width: 900px !important;\n	margin: 56px auto 0 !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-title,\n.single .entry-title {\n	font-size: clamp(42px, 6vw, 72px) !important;\n	line-height: 0.98 !important;\n	margin: 0 !important;\n	color: var(--skn-green);\n}\n\n.page .entry-content,\n.single .entry-content {\n	max-width: 760px !important;\n	margin: 32px auto 72px !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-content > *,\n.single .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.page .entry-content .wp-block-group__inner-container > *,\n.single .entry-content .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.skn-required-page {\n	position: relative;\n}\n\n.skn-page-heading {\n	font-size: clamp(34px, 4.5vw, 52px) !important;\n	margin: 0 0 18px !important;\n}\n\n.skn-lead {\n	font-size: 20px !important;\n	line-height: 1.7 !important;\n	color: var(--skn-ink) !important;\n}\n\n.skn-note-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-terra);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-size: 16px !important;\n	font-weight: 600;\n	color: var(--skn-green) !important;\n	margin: 28px 0 0 !important;\n}\n\n.skn-verify-line {\n	border-left-color: var(--skn-mustard);\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	font-family: ui-monospace, SFMono-Regular, Consolas, monospace;\n	letter-spacing: 0.02em;\n}\n\n.skn-verify-line::before {\n	content: \"✓ \";\n	color: var(--skn-mustard);\n}\n\n/* ---------------------------------------------------------\n   Single posts\n   --------------------------------------------------------- */\n\n.single .entry-header .post-thumbnail {\n	display: none !important;\n}\n\n.single .entry-content p {\n	font-size: 18px;\n	line-height: 1.85;\n}\n\n.skn-post-image {\n	margin: 36px 0 !important;\n}\n\n.skn-post-image img {\n	border-radius: 16px;\n	box-shadow: 0 20px 50px rgba(18, 59, 50, 0.15);\n}\n\n.skn-schedule-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-mustard);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-weight: 700;\n	color: var(--skn-green) !important;\n	margin-top: 28px !important;\n}\n\n.single .entry-footer {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 24px 32px 0 !important;\n	border-top: 1px solid var(--skn-line);\n	font-size: 13px;\n	color: var(--skn-muted);\n}\n\n.single .entry-footer .posted-by {\n	margin-bottom: 8px;\n}\n\n.single .entry-footer .post-taxonomies {\n	margin-top: 8px;\n}\n\n.single .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n.single .author-bio {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 0 32px !important;\n}\n\n/* ---------------------------------------------------------\n   Blog & archives\n   --------------------------------------------------------- */\n\n.blog .site-main,\n.archive .site-main {\n	max-width: 1100px !important;\n	margin: 0 auto !important;\n	padding: 0 32px 80px !important;\n}\n\n.blog .page-header,\n.archive .page-header {\n	max-width: 100% !important;\n	margin: 56px 0 32px !important;\n	padding: 0 !important;\n}\n\n.blog .page-title,\n.archive .page-title {\n	font-size: clamp(40px, 5vw, 64px) !important;\n	margin: 0 !important;\n}\n\n.blog article,\n.archive article {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 28px !important;\n	margin-bottom: 24px;\n	display: grid;\n	grid-template-columns: 240px 1fr;\n	grid-template-rows: auto auto auto;\n	gap: 0 28px;\n	align-items: center;\n}\n\n.blog article .entry-header,\n.archive article .entry-header {\n	display: contents;\n}\n\n.blog article .entry-header .post-thumbnail,\n.archive article .entry-header .post-thumbnail {\n	grid-column: 1;\n	grid-row: 1 / span 3;\n	margin: 0 !important;\n}\n\n.blog article .entry-header .post-thumbnail img,\n.archive article .entry-header .post-thumbnail img {\n	border-radius: 12px;\n	width: 100%;\n	height: 100%;\n	object-fit: cover;\n}\n\n.blog article .entry-header .entry-title,\n.archive article .entry-header .entry-title {\n	grid-column: 2;\n	grid-row: 1;\n	font-size: 30px !important;\n	margin: 0 !important;\n}\n\n.blog article .entry-content,\n.archive article .entry-content {\n	grid-column: 2;\n	grid-row: 2;\n	margin: 8px 0 0 !important;\n	max-width: none !important;\n}\n\n.blog article .entry-content p,\n.archive article .entry-content p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	margin: 0;\n}\n\n.blog article .entry-footer,\n.archive article .entry-footer {\n	grid-column: 2;\n	grid-row: 3;\n	margin: 8px 0 0 !important;\n	padding: 0 !important;\n	border: 0 !important;\n}\n\n.blog article .entry-footer a,\n.archive article .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n/* ---------------------------------------------------------\n   Footer\n   --------------------------------------------------------- */\n\n.site-footer {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 48px 0 36px !important;\n	background: var(--skn-green-deep);\n	color: var(--skn-cream);\n}\n\n.site-footer > .footer-navigation,\n.site-footer > .site-info {\n	max-width: 1200px;\n	margin-left: auto;\n	margin-right: auto;\n	padding-left: 32px;\n	padding-right: 32px;\n}\n\n.site-footer .footer-navigation-wrapper {\n	display: flex;\n	gap: 24px;\n	list-style: none;\n	margin: 0 0 24px;\n	padding: 0;\n}\n\n.site-footer .footer-navigation-wrapper a {\n	color: rgba(247, 241, 230, 0.7);\n	font-size: 11px;\n	letter-spacing: 0.14em;\n	text-transform: uppercase;\n	text-decoration: none;\n}\n\n.site-footer .footer-navigation-wrapper a:hover {\n	color: var(--skn-mustard);\n}\n\n.site-footer > .site-info {\n	border-top: 1px solid rgba(247, 241, 230, 0.18);\n	padding-top: 24px;\n	display: flex;\n	align-items: center;\n	justify-content: space-between;\n	gap: 16px;\n}\n\n.site-footer .site-info .site-name {\n	font-family: var(--skn-serif);\n	font-size: 18px;\n}\n\n.site-footer .site-info .site-logo .custom-logo {\n	width: 44px;\n	height: 44px;\n	max-height: 44px;\n}\n\n.site-footer .powered-by,\n.site-footer .privacy-policy {\n	display: none !important;\n}\n\n.site-footer .site-info::after {\n	content: \"Ruang kreasi dan berbagi ide\";\n	font-size: 12px;\n	letter-spacing: 0.08em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.55);\n}\n\n/* ---------------------------------------------------------\n   Responsive\n   --------------------------------------------------------- */\n\n@media (max-width: 1024px) {\n	.skn-hero-title {\n		font-size: clamp(48px, 8vw, 76px) !important;\n	}\n\n	.skn-hero-cols {\n		gap: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 340px);\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 420px;\n	}\n}\n\n@media (max-width: 821px) {\n	.site-header {\n		position: relative;\n		flex-wrap: wrap;\n		padding: 16px 20px !important;\n		gap: 12px;\n	}\n\n	.site-header .custom-logo {\n		width: 44px;\n		height: 44px;\n	}\n\n	.site-title {\n		font-size: 22px !important;\n	}\n\n	.site-description {\n		font-size: 10px !important;\n	}\n\n	.primary-navigation {\n		width: 100%;\n		margin-left: 0;\n	}\n\n	.skn-container {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.skn-hero {\n		padding: 56px 0 64px;\n	}\n\n	.skn-hero-cols {\n		flex-direction: column;\n	}\n\n	.skn-hero-copy {\n		padding-right: 0;\n	}\n\n	.skn-hero-visual {\n		justify-content: flex-start;\n		margin-top: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 320px);\n		transform: rotate(1.5deg);\n	}\n\n	.skn-values {\n		padding: 40px 0;\n	}\n\n	.skn-values-grid .wp-block-column {\n		border-left: 0;\n		border-top: 1px solid var(--skn-line);\n		padding: 20px 0 0;\n		margin-top: 20px;\n	}\n\n	.skn-values-grid .wp-block-column:first-child {\n		border-top: 0;\n		margin-top: 0;\n		padding-top: 0;\n	}\n\n	.skn-programs,\n	.skn-works,\n	.skn-agenda {\n		padding: 64px 0;\n	}\n\n	.skn-card-grid {\n		flex-direction: column;\n	}\n\n	.skn-card-grid .wp-block-column {\n		width: 100%;\n	}\n\n	.skn-works-grid,\n	.skn-agenda-grid {\n		flex-direction: column;\n		gap: 32px;\n	}\n\n	.skn-works-grid .wp-block-column,\n	.skn-agenda-grid .wp-block-column {\n		width: 100% !important;\n		flex-basis: 100% !important;\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 380px;\n	}\n\n	.skn-cta {\n		padding: 64px 0;\n	}\n\n	.page .entry-header,\n	.single .entry-header {\n		margin-top: 32px !important;\n		padding: 0 20px !important;\n	}\n\n	.page .entry-content,\n	.single .entry-content {\n		padding: 0 20px !important;\n		margin-top: 24px !important;\n	}\n\n	.page .entry-title,\n	.single .entry-title {\n		font-size: clamp(34px, 9vw, 48px) !important;\n	}\n\n	.blog .site-main,\n	.archive .site-main {\n		padding: 0 20px 64px !important;\n	}\n\n	.blog article,\n	.archive article {\n		grid-template-columns: 1fr;\n		padding: 20px !important;\n	}\n\n	.blog article .entry-header,\n	.archive article .entry-header {\n		display: block;\n	}\n\n	.blog article .entry-header .post-thumbnail,\n	.archive article .entry-header .post-thumbnail {\n		margin-bottom: 16px !important;\n	}\n\n	.blog article .entry-header .entry-title,\n	.archive article .entry-header .entry-title {\n		font-size: 26px !important;\n	}\n\n	.site-footer > .footer-navigation,\n	.site-footer > .site-info {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.site-footer > .site-info {\n		flex-direction: column;\n		align-items: flex-start;\n	}\n\n	.site-footer .site-info::after {\n		margin-top: 8px;\n	}\n}\n','twentytwentyone','','inherit','closed','closed','','27-revision-v1','','','2026-10-27 19:18:28','2026-10-27 11:18:28','',27,'http://localhost:8080/?p=29',0,'revision','',0),
(30,0,'2026-10-27 19:19:29','2026-10-27 11:19:29','/* =========================================================\n   Studio Karya Nusa — custom theme styles\n   Theme: Twenty Twenty-One\n   ========================================================= */\n\n:root {\n	--skn-green: #123b32;\n	--skn-green-deep: #0c2a24;\n	--skn-cream: #f7f1e6;\n	--skn-cream-soft: #fbf7ef;\n	--skn-terra: #d97757;\n	--skn-mustard: #e3b23c;\n	--skn-ink: #1f2421;\n	--skn-muted: #5e6a63;\n	--skn-line: rgba(18, 59, 50, 0.16);\n	--skn-serif: Georgia, \"Times New Roman\", serif;\n	--skn-sans: \"Segoe UI\", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;\n\n	--global--color-primary: var(--skn-green);\n	--global--color-primary-hover: var(--skn-terra);\n	--global--color-background: var(--skn-cream);\n	--global--color-secondary: var(--skn-terra);\n	--global--color-border: var(--skn-line);\n	--global--font-primary: var(--skn-serif);\n	--global--font-secondary: var(--skn-sans);\n	--branding--title--font-family: var(--skn-serif);\n	--branding--description--font-family: var(--skn-sans);\n	--entry-header--font-family: var(--skn-serif);\n	--footer--color-text: var(--skn-cream);\n}\n\nhtml {\n	scroll-behavior: smooth;\n}\n\nbody {\n	background: var(--skn-cream);\n	color: var(--skn-ink);\n	font-family: var(--skn-sans);\n	font-size: 17px;\n	line-height: 1.75;\n	-webkit-font-smoothing: antialiased;\n}\n\n::selection {\n	background: var(--skn-terra);\n	color: var(--skn-cream);\n}\n\nh1, h2, h3, h4, h5, h6,\n.site-title,\n.entry-title,\n.page-title {\n	font-family: var(--skn-serif);\n	color: var(--skn-green);\n	line-height: 1.08;\n	letter-spacing: -0.02em;\n}\n\na {\n	color: var(--skn-green);\n	text-decoration-thickness: 1px;\n	text-underline-offset: 3px;\n}\n\na:hover,\na:focus {\n	color: var(--skn-terra);\n}\n\n/* ---------------------------------------------------------\n   Header\n   --------------------------------------------------------- */\n\n.site-header {\n	max-width: 1240px !important;\n	margin: 0 auto !important;\n	padding: 22px 32px !important;\n	display: flex !important;\n	align-items: center;\n	gap: 18px;\n	position: sticky;\n	top: 0;\n	z-index: 100;\n	background: rgba(247, 241, 230, 0.96);\n	backdrop-filter: blur(12px);\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.site-header > .site-logo {\n	width: auto !important;\n	padding: 0 !important;\n	border: 0 !important;\n	margin: 0 !important;\n	flex: 0 0 auto;\n}\n\n.site-header .custom-logo {\n	width: 54px;\n	height: 54px;\n	max-height: 54px;\n	max-width: 54px;\n	object-fit: contain;\n	border-radius: 50%;\n}\n\n.site-branding {\n	margin: 0 !important;\n	flex: 1 1 auto;\n	min-width: 0;\n}\n\n.site-title {\n	font-size: 26px !important;\n	line-height: 1.05 !important;\n	margin: 0 !important;\n	letter-spacing: -0.02em;\n}\n\n.site-title a {\n	color: var(--skn-green) !important;\n	text-decoration: none;\n}\n\n.site-description {\n	margin: 5px 0 0 !important;\n	font-size: 11px !important;\n	letter-spacing: 0.16em;\n	text-transform: uppercase;\n	color: var(--skn-muted) !important;\n	line-height: 1.4;\n}\n\n.primary-navigation {\n	margin-left: auto;\n}\n\n@media only screen and (min-width: 822px) {\n	#primary-menu-list {\n		display: flex;\n		align-items: center;\n		gap: 28px;\n		margin: 0;\n		padding: 0;\n		list-style: none;\n	}\n\n	#primary-menu-list li {\n		margin: 0;\n	}\n\n	#primary-menu-list a {\n		font-size: 12px;\n		font-weight: 600;\n		letter-spacing: 0.12em;\n		text-transform: uppercase;\n		text-decoration: none;\n		color: var(--skn-green);\n		padding: 6px 0;\n		position: relative;\n	}\n\n	#primary-menu-list a::after {\n		content: \"\";\n		position: absolute;\n		left: 0;\n		right: 0;\n		bottom: 0;\n		height: 2px;\n		background: var(--skn-terra);\n		transform: scaleX(0);\n		transform-origin: left;\n		transition: transform 0.2s ease;\n	}\n\n	#primary-menu-list a:hover::after,\n	#primary-menu-list .current-menu-item > a::after {\n		transform: scaleX(1);\n	}\n\n	#primary-menu-list .current-menu-item > a {\n		color: var(--skn-terra);\n	}\n\n	.menu-button-container {\n		display: none;\n	}\n}\n\n/* ---------------------------------------------------------\n   Home layout\n   --------------------------------------------------------- */\n\nbody.home .site-content {\n	padding: 0 !important;\n}\n\nbody.home .content-area,\nbody.home .site-main {\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\nbody.home .entry-content .wp-block-group__inner-container > *,\nbody.home .entry-content .wp-block-columns,\nbody.home .entry-content .wp-block-column,\nbody.home .entry-content .wp-block-latest-posts {\n	max-width: none !important;\n}\n\n.skn-container {\n	max-width: 1200px !important;\n	margin-left: auto !important;\n	margin-right: auto !important;\n	padding-left: 32px;\n	padding-right: 32px;\n	box-sizing: border-box;\n}\n\n.skn-container > .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Hero\n   --------------------------------------------------------- */\n\n.skn-hero {\n	background:\n		radial-gradient(circle at 82% 18%, rgba(227, 178, 60, 0.18), transparent 32%),\n		radial-gradient(circle at 12% 88%, rgba(217, 119, 87, 0.16), transparent 36%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green) 60%, #1b4d42);\n	color: var(--skn-cream);\n	padding: 92px 0 96px;\n	position: relative;\n	overflow: hidden;\n}\n\n.skn-hero::before {\n	content: \"\";\n	position: absolute;\n	inset: 0;\n	background-image: radial-gradient(rgba(247, 241, 230, 0.08) 1px, transparent 1px);\n	background-size: 26px 26px;\n	opacity: 0.35;\n	pointer-events: none;\n}\n\n.skn-hero-inner {\n	position: relative;\n	z-index: 1;\n}\n\n.skn-hero-cols {\n	align-items: center;\n	gap: 48px;\n}\n\n.skn-hero-copy {\n	padding-right: 20px;\n}\n\n.skn-hero-kicker {\n	font-size: 11px;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-mustard);\n	margin: 0 0 18px;\n	font-weight: 700;\n}\n\n.skn-hero-title {\n	font-size: clamp(56px, 7vw, 104px) !important;\n	line-height: 0.92 !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 22px !important;\n	letter-spacing: -0.045em !important;\n}\n\n.skn-hero-tagline {\n	font-family: var(--skn-serif);\n	font-size: clamp(22px, 2.4vw, 32px);\n	font-style: italic;\n	color: var(--skn-cream) !important;\n	margin: 0 0 18px;\n	line-height: 1.2;\n}\n\n.skn-hero-text {\n	font-size: 17px;\n	line-height: 1.75;\n	color: rgba(247, 241, 230, 0.78);\n	max-width: 520px;\n	margin: 0 0 32px;\n}\n\n.skn-hero-buttons {\n	gap: 14px;\n}\n\n.skn-btn .wp-block-button__link {\n	border-radius: 999px;\n	padding: 14px 26px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease;\n}\n\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link,\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link:not(:hover):not(:active) {\n	background-color: var(--skn-terra) !important;\n	color: var(--skn-cream) !important;\n	border-color: var(--skn-terra) !important;\n}\n\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link:hover {\n	background-color: var(--skn-mustard) !important;\n	color: var(--skn-green-deep) !important;\n	border-color: var(--skn-mustard) !important;\n	transform: translateY(-2px);\n}\n\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link,\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:not(:hover):not(:active) {\n	background-color: transparent !important;\n	color: var(--skn-cream) !important;\n	border-color: rgba(247, 241, 230, 0.45) !important;\n}\n\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:hover {\n	background-color: var(--skn-cream) !important;\n	color: var(--skn-green) !important;\n	border-color: var(--skn-cream) !important;\n	transform: translateY(-2px);\n}\n\n.skn-hero-visual {\n	display: flex;\n	justify-content: flex-end;\n}\n\n.skn-hero-poster {\n	margin: 0 !important;\n	width: min(100%, 420px);\n	transform: rotate(2.5deg);\n}\n\n.skn-hero-poster img {\n	width: 100%;\n	height: auto;\n	border: 10px solid var(--skn-cream);\n	border-radius: 6px;\n	box-shadow: 0 30px 70px rgba(0, 0, 0, 0.35);\n	display: block;\n}\n\n/* ---------------------------------------------------------\n   Values\n   --------------------------------------------------------- */\n\n.skn-values {\n	background: var(--skn-cream);\n	padding: 64px 0 56px;\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.skn-values-grid {\n	gap: 0;\n}\n\n.skn-values-grid .wp-block-column {\n	padding: 0 28px;\n	border-left: 1px solid var(--skn-line);\n}\n\n.skn-values-grid .wp-block-column:first-child {\n	border-left: 0;\n	padding-left: 0;\n}\n\n.skn-value-num {\n	font-family: var(--skn-serif);\n	font-size: 14px;\n	color: var(--skn-terra);\n	letter-spacing: 0.1em;\n	margin: 0 0 10px;\n}\n\n.skn-value-title {\n	font-size: 30px !important;\n	margin: 0 0 8px !important;\n}\n\n.skn-values p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0;\n	line-height: 1.65;\n}\n\n/* ---------------------------------------------------------\n   Programs\n   --------------------------------------------------------- */\n\n.skn-programs {\n	background: var(--skn-cream-soft);\n	padding: 96px 0;\n}\n\n.skn-section-head {\n	max-width: 720px !important;\n	margin: 0 0 44px !important;\n}\n\n.skn-kicker {\n	font-size: 11px;\n	font-weight: 700;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-terra);\n	margin: 0 0 12px;\n}\n\n.skn-section-title {\n	font-size: clamp(36px, 4vw, 56px) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-section-lead {\n	font-size: 17px;\n	color: var(--skn-muted);\n	line-height: 1.7;\n	margin: 0;\n	max-width: 620px;\n}\n\n.skn-card-grid {\n	gap: 24px;\n	align-items: stretch;\n}\n\n.skn-card-grid .wp-block-column {\n	display: flex;\n}\n\n.skn-card {\n	background: var(--skn-cream);\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 30px 28px 26px !important;\n	width: 100%;\n	display: flex;\n	flex-direction: column;\n	transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;\n}\n\n.skn-card:hover {\n	transform: translateY(-6px);\n	box-shadow: 0 18px 40px rgba(18, 59, 50, 0.1);\n	border-color: rgba(217, 119, 87, 0.45);\n}\n\n.skn-card-num {\n	font-family: var(--skn-serif);\n	font-size: 13px;\n	letter-spacing: 0.12em;\n	color: var(--skn-terra);\n	margin: 0 0 22px;\n}\n\n.skn-card h3 {\n	font-size: 25px !important;\n	margin: 0 0 10px !important;\n	line-height: 1.15 !important;\n}\n\n.skn-card p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0 0 18px;\n	line-height: 1.65;\n}\n\n.skn-card-link {\n	margin-top: auto !important;\n}\n\n.skn-card-link a,\n.skn-section-link a {\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.1em;\n	text-transform: uppercase;\n	text-decoration: none;\n	color: var(--skn-terra);\n	border-bottom: 1px solid rgba(217, 119, 87, 0.4);\n	padding-bottom: 2px;\n}\n\n.skn-card-link a:hover,\n.skn-section-link a:hover {\n	color: var(--skn-green);\n	border-color: var(--skn-green);\n}\n\n/* ---------------------------------------------------------\n   Works\n   --------------------------------------------------------- */\n\n.skn-works {\n	background: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-works-grid {\n	gap: 56px;\n}\n\n.skn-works .skn-section-title {\n	font-size: clamp(34px, 4vw, 52px) !important;\n}\n\n.skn-latest {\n	display: block !important;\n	margin: 0 !important;\n	padding: 0 !important;\n	list-style: none !important;\n}\n\n.skn-latest li {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 20px;\n	overflow: hidden;\n	padding: 0 !important;\n	margin: 0 !important;\n	box-shadow: 0 18px 50px rgba(18, 59, 50, 0.08);\n	display: grid;\n	grid-template-columns: 42% 1fr;\n	align-items: stretch;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image {\n	margin: 0 !important;\n	grid-row: 1 / span 2;\n	background: var(--skn-green);\n	padding: 18px;\n	display: flex;\n	align-items: center;\n	justify-content: center;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image img {\n	width: 100% !important;\n	height: auto !important;\n	max-height: 420px;\n	object-fit: contain;\n	display: block;\n	box-shadow: 0 14px 30px rgba(0, 0, 0, 0.28);\n}\n\n.skn-latest .wp-block-latest-posts__post-title {\n	display: block;\n	font-family: var(--skn-serif);\n	font-size: 30px;\n	line-height: 1.15;\n	color: var(--skn-green);\n	text-decoration: none;\n	padding: 28px 30px 0;\n}\n\n.skn-latest .wp-block-latest-posts__post-title:hover {\n	color: var(--skn-terra);\n}\n\n.skn-latest .wp-block-latest-posts__post-excerpt {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	padding: 10px 30px 28px;\n	margin: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Agenda\n   --------------------------------------------------------- */\n\n.skn-agenda {\n	background:\n		radial-gradient(circle at 90% 10%, rgba(227, 178, 60, 0.16), transparent 30%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green));\n	color: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-agenda .skn-section-title {\n	color: var(--skn-cream) !important;\n}\n\n.skn-agenda .skn-kicker {\n	color: var(--skn-mustard);\n}\n\n.skn-agenda .skn-section-lead {\n	color: rgba(247, 241, 230, 0.75);\n}\n\n.skn-agenda .skn-section-link a {\n	color: var(--skn-mustard);\n	border-color: rgba(227, 178, 60, 0.5);\n}\n\n.skn-agenda .skn-section-link a:hover {\n	color: var(--skn-cream);\n	border-color: var(--skn-cream);\n}\n\n.skn-latest-agenda li {\n	background: #fffaf2;\n}\n\n/* ---------------------------------------------------------\n   CTA\n   --------------------------------------------------------- */\n\n.skn-cta {\n	background:\n		radial-gradient(circle at 15% 20%, rgba(247, 241, 230, 0.12), transparent 30%),\n		var(--skn-terra);\n	color: var(--skn-cream);\n	padding: 88px 0;\n	text-align: center;\n}\n\n.skn-cta-inner {\n	max-width: 820px !important;\n}\n\n.skn-cta .skn-kicker {\n	color: var(--skn-green-deep);\n}\n\n.skn-cta-title {\n	font-size: clamp(40px, 5vw, 64px) !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-cta-text {\n	font-size: 18px;\n	color: rgba(247, 241, 230, 0.85);\n	max-width: 620px;\n	margin: 0 auto 28px;\n}\n\n.skn-cta-actions {\n	margin: 0 0 24px !important;\n}\n\n.skn-cta-button {\n	display: inline-block;\n	background: var(--skn-cream);\n	color: var(--skn-green) !important;\n	border-radius: 999px;\n	padding: 14px 30px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease;\n}\n\n.skn-cta-button:hover {\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	transform: translateY(-2px);\n}\n\n.skn-cta-location {\n	font-size: 11px;\n	letter-spacing: 0.18em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.65);\n	margin: 0;\n}\n\n/* ---------------------------------------------------------\n   Required pages\n   --------------------------------------------------------- */\n\n.page .site-main,\n.single .site-main {\n	padding-top: 0;\n}\n\n.page .entry-header,\n.single .entry-header {\n	max-width: 900px !important;\n	margin: 56px auto 0 !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-title,\n.single .entry-title {\n	font-size: clamp(42px, 6vw, 72px) !important;\n	line-height: 0.98 !important;\n	margin: 0 !important;\n	color: var(--skn-green);\n}\n\n.page .entry-content,\n.single .entry-content {\n	max-width: 760px !important;\n	margin: 32px auto 72px !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-content > *,\n.single .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.page .entry-content .wp-block-group__inner-container > *,\n.single .entry-content .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.skn-required-page {\n	position: relative;\n}\n\n.skn-page-heading {\n	font-size: clamp(34px, 4.5vw, 52px) !important;\n	margin: 0 0 18px !important;\n}\n\n.skn-lead {\n	font-size: 20px !important;\n	line-height: 1.7 !important;\n	color: var(--skn-ink) !important;\n}\n\n.skn-note-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-terra);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-size: 16px !important;\n	font-weight: 600;\n	color: var(--skn-green) !important;\n	margin: 28px 0 0 !important;\n}\n\n.skn-verify-line {\n	border-left-color: var(--skn-mustard);\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	font-family: ui-monospace, SFMono-Regular, Consolas, monospace;\n	letter-spacing: 0.02em;\n}\n\n.skn-verify-line::before {\n	content: \"✓ \";\n	color: var(--skn-mustard);\n}\n\n/* ---------------------------------------------------------\n   Single posts\n   --------------------------------------------------------- */\n\n.single .entry-header .post-thumbnail {\n	display: none !important;\n}\n\n.single .entry-content p {\n	font-size: 18px;\n	line-height: 1.85;\n}\n\n.skn-post-image {\n	margin: 36px 0 !important;\n}\n\n.skn-post-image img {\n	border-radius: 16px;\n	box-shadow: 0 20px 50px rgba(18, 59, 50, 0.15);\n}\n\n.skn-schedule-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-mustard);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-weight: 700;\n	color: var(--skn-green) !important;\n	margin-top: 28px !important;\n}\n\n.single .entry-footer {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 24px 32px 0 !important;\n	border-top: 1px solid var(--skn-line);\n	font-size: 13px;\n	color: var(--skn-muted);\n}\n\n.single .entry-footer .posted-by {\n	margin-bottom: 8px;\n}\n\n.single .entry-footer .post-taxonomies {\n	margin-top: 8px;\n}\n\n.single .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n.single .author-bio {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 0 32px !important;\n}\n\n/* ---------------------------------------------------------\n   Blog & archives\n   --------------------------------------------------------- */\n\n.blog .site-main,\n.archive .site-main {\n	max-width: 1100px !important;\n	margin: 0 auto !important;\n	padding: 0 32px 80px !important;\n}\n\n.blog .page-header,\n.archive .page-header {\n	max-width: 100% !important;\n	margin: 56px 0 32px !important;\n	padding: 0 !important;\n}\n\n.blog .page-title,\n.archive .page-title {\n	font-size: clamp(40px, 5vw, 64px) !important;\n	margin: 0 !important;\n}\n\n.blog article,\n.archive article {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 28px !important;\n	margin-bottom: 24px;\n	display: grid;\n	grid-template-columns: 240px 1fr;\n	grid-template-rows: auto auto auto;\n	gap: 0 28px;\n	align-items: center;\n}\n\n.blog article .entry-header,\n.archive article .entry-header {\n	display: contents;\n}\n\n.blog article .entry-header .post-thumbnail,\n.archive article .entry-header .post-thumbnail {\n	grid-column: 1;\n	grid-row: 1 / span 3;\n	margin: 0 !important;\n}\n\n.blog article .entry-header .post-thumbnail img,\n.archive article .entry-header .post-thumbnail img {\n	border-radius: 12px;\n	width: 100%;\n	height: 100%;\n	object-fit: cover;\n}\n\n.blog article .entry-header .entry-title,\n.archive article .entry-header .entry-title {\n	grid-column: 2;\n	grid-row: 1;\n	font-size: 30px !important;\n	margin: 0 !important;\n}\n\n.blog article .entry-content,\n.archive article .entry-content {\n	grid-column: 2;\n	grid-row: 2;\n	margin: 8px 0 0 !important;\n	max-width: none !important;\n}\n\n.blog article .entry-content p,\n.archive article .entry-content p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	margin: 0;\n}\n\n.blog article .entry-footer,\n.archive article .entry-footer {\n	grid-column: 2;\n	grid-row: 3;\n	margin: 8px 0 0 !important;\n	padding: 0 !important;\n	border: 0 !important;\n}\n\n.blog article .entry-footer a,\n.archive article .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n/* ---------------------------------------------------------\n   Footer\n   --------------------------------------------------------- */\n\n.site-footer {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 48px 0 36px !important;\n	background: var(--skn-green-deep);\n	color: var(--skn-cream);\n}\n\n.site-footer > .footer-navigation,\n.site-footer > .site-info {\n	max-width: 1200px;\n	margin-left: auto;\n	margin-right: auto;\n	padding-left: 32px;\n	padding-right: 32px;\n}\n\n.site-footer .footer-navigation {\n	text-align: left;\n	margin: 0 0 20px;\n}\n\n.site-footer .footer-navigation-wrapper {\n	display: flex;\n	justify-content: flex-start !important;\n	gap: 24px;\n	list-style: none;\n	margin: 0;\n	padding: 0;\n}\n\n.site-footer .footer-navigation-wrapper li {\n	line-height: 1.2;\n	margin: 0;\n}\n\n.site-footer .footer-navigation-wrapper li a,\n.site-footer .footer-navigation-wrapper li a:link,\n.site-footer .footer-navigation-wrapper li a:visited,\n.site-footer .footer-navigation-wrapper li a:active {\n	color: rgba(247, 241, 230, 0.72) !important;\n	font-size: 11px;\n	letter-spacing: 0.14em;\n	text-transform: uppercase;\n	text-decoration: none;\n	padding: 6px 0;\n}\n\n.site-footer .footer-navigation-wrapper li a:hover {\n	color: var(--skn-mustard) !important;\n}\n\n.site-footer > .site-info {\n	border-top: 1px solid rgba(247, 241, 230, 0.18);\n	padding-top: 24px;\n	display: flex;\n	align-items: center;\n	justify-content: space-between;\n	gap: 16px;\n}\n\n.site-footer .site-info .site-name {\n	font-family: var(--skn-serif);\n	font-size: 18px;\n}\n\n.site-footer .site-info .site-logo .custom-logo {\n	width: 44px;\n	height: 44px;\n	max-height: 44px;\n}\n\n.site-footer .powered-by,\n.site-footer .privacy-policy {\n	display: none !important;\n}\n\n.site-footer .site-info::after {\n	content: \"Ruang kreasi dan berbagi ide\";\n	font-size: 12px;\n	letter-spacing: 0.08em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.55);\n}\n\n/* ---------------------------------------------------------\n   Responsive\n   --------------------------------------------------------- */\n\n@media (max-width: 1024px) {\n	.skn-hero-title {\n		font-size: clamp(48px, 8vw, 76px) !important;\n	}\n\n	.skn-hero-cols {\n		gap: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 340px);\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 420px;\n	}\n}\n\n@media (max-width: 821px) {\n	.site-header {\n		position: relative;\n		flex-wrap: wrap;\n		padding: 16px 20px !important;\n		gap: 12px;\n	}\n\n	.site-header .custom-logo {\n		width: 44px;\n		height: 44px;\n	}\n\n	.site-title {\n		font-size: 22px !important;\n	}\n\n	.site-description {\n		font-size: 10px !important;\n	}\n\n	.primary-navigation {\n		width: 100%;\n		margin-left: 0;\n	}\n\n	.skn-container {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.skn-hero {\n		padding: 56px 0 64px;\n	}\n\n	.skn-hero-cols {\n		flex-direction: column;\n	}\n\n	.skn-hero-copy {\n		padding-right: 0;\n	}\n\n	.skn-hero-visual {\n		justify-content: flex-start;\n		margin-top: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 320px);\n		transform: rotate(1.5deg);\n	}\n\n	.skn-values {\n		padding: 40px 0;\n	}\n\n	.skn-values-grid .wp-block-column {\n		border-left: 0;\n		border-top: 1px solid var(--skn-line);\n		padding: 20px 0 0;\n		margin-top: 20px;\n	}\n\n	.skn-values-grid .wp-block-column:first-child {\n		border-top: 0;\n		margin-top: 0;\n		padding-top: 0;\n	}\n\n	.skn-programs,\n	.skn-works,\n	.skn-agenda {\n		padding: 64px 0;\n	}\n\n	.skn-card-grid {\n		flex-direction: column;\n	}\n\n	.skn-card-grid .wp-block-column {\n		width: 100%;\n	}\n\n	.skn-works-grid,\n	.skn-agenda-grid {\n		flex-direction: column;\n		gap: 32px;\n	}\n\n	.skn-works-grid .wp-block-column,\n	.skn-agenda-grid .wp-block-column {\n		width: 100% !important;\n		flex-basis: 100% !important;\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 380px;\n	}\n\n	.skn-cta {\n		padding: 64px 0;\n	}\n\n	.page .entry-header,\n	.single .entry-header {\n		margin-top: 32px !important;\n		padding: 0 20px !important;\n	}\n\n	.page .entry-content,\n	.single .entry-content {\n		padding: 0 20px !important;\n		margin-top: 24px !important;\n	}\n\n	.page .entry-title,\n	.single .entry-title {\n		font-size: clamp(34px, 9vw, 48px) !important;\n	}\n\n	.blog .site-main,\n	.archive .site-main {\n		padding: 0 20px 64px !important;\n	}\n\n	.blog article,\n	.archive article {\n		grid-template-columns: 1fr;\n		padding: 20px !important;\n	}\n\n	.blog article .entry-header,\n	.archive article .entry-header {\n		display: block;\n	}\n\n	.blog article .entry-header .post-thumbnail,\n	.archive article .entry-header .post-thumbnail {\n		margin-bottom: 16px !important;\n	}\n\n	.blog article .entry-header .entry-title,\n	.archive article .entry-header .entry-title {\n		font-size: 26px !important;\n	}\n\n	.site-footer > .footer-navigation,\n	.site-footer > .site-info {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.site-footer > .site-info {\n		flex-direction: column;\n		align-items: flex-start;\n	}\n\n	.site-footer .site-info::after {\n		margin-top: 8px;\n	}\n}\n','twentytwentyone','','inherit','closed','closed','','27-revision-v1','','','2026-10-27 19:19:29','2026-10-27 11:19:29','',27,'http://localhost:8080/?p=30',0,'revision','',0),
(31,0,'2026-10-27 19:20:09','2026-10-27 11:20:09','<!-- wp:paragraph -->\n<p>Anggota Studio Karya Nusa mengumpulkan poster dengan tema lingkungan sekitar. Setiap karya diberi judul dan penjelasan singkat.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":4,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"className\":\"skn-post-image\"} -->\n<figure class=\"wp-block-image size-large skn-post-image\"><img src=\"http://localhost:8080/wp-content/uploads/2026/10/c_studio.jpg\" alt=\"Poster Galeri Poster Komunitas Studio Karya Nusa bertema lingkungan sekitar\" class=\"wp-image-4\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>Galeri membantu anggota belajar menyampaikan pesan secara visual. Pengunjung dapat membaca deskripsi karya dan memberikan masukan saat diskusi.</p>\n<!-- /wp:paragraph -->\n','Galeri Poster Komunitas','Anggota Studio Karya Nusa mengumpulkan poster bertema lingkungan sekitar. Setiap karya diberi judul dan penjelasan singkat.','inherit','closed','closed','','12-revision-v1','','','2026-10-27 19:20:09','2026-10-27 11:20:09','',12,'http://localhost:8080/?p=31',0,'revision','',0),
(32,0,'2026-10-27 19:20:11','2026-10-27 11:20:11','<!-- wp:paragraph -->\n<p>Studio Karya Nusa mengadakan lokakarya poster digital bagi peserta pemula. Peserta berlatih menyusun judul, gambar, dan pesan utama.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Fasilitator menyiapkan contoh dan panduan langkah demi langkah. Peserta dapat menyelesaikan satu poster sederhana selama sesi.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"className\":\"skn-schedule-line\"} -->\n<p class=\"skn-schedule-line\">Jadwal khusus: Jumat, 14.00 WITA</p>\n<!-- /wp:paragraph -->\n','Lokakarya Poster Digital','Lokakarya poster digital untuk peserta pemula. Jadwal khusus: Jumat, 14.00 WITA.','inherit','closed','closed','','13-revision-v1','','','2026-10-27 19:20:11','2026-10-27 11:20:11','',13,'http://localhost:8080/?p=32',0,'revision','',0),
(33,0,'2026-10-27 19:21:04','2026-10-27 11:21:04','/* =========================================================\n   Studio Karya Nusa — custom theme styles\n   Theme: Twenty Twenty-One\n   ========================================================= */\n\n:root {\n	--skn-green: #123b32;\n	--skn-green-deep: #0c2a24;\n	--skn-cream: #f7f1e6;\n	--skn-cream-soft: #fbf7ef;\n	--skn-terra: #d97757;\n	--skn-mustard: #e3b23c;\n	--skn-ink: #1f2421;\n	--skn-muted: #5e6a63;\n	--skn-line: rgba(18, 59, 50, 0.16);\n	--skn-serif: Georgia, \"Times New Roman\", serif;\n	--skn-sans: \"Segoe UI\", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;\n\n	--global--color-primary: var(--skn-green);\n	--global--color-primary-hover: var(--skn-terra);\n	--global--color-background: var(--skn-cream);\n	--global--color-secondary: var(--skn-terra);\n	--global--color-border: var(--skn-line);\n	--global--font-primary: var(--skn-serif);\n	--global--font-secondary: var(--skn-sans);\n	--branding--title--font-family: var(--skn-serif);\n	--branding--description--font-family: var(--skn-sans);\n	--entry-header--font-family: var(--skn-serif);\n	--footer--color-text: var(--skn-cream);\n}\n\nhtml {\n	scroll-behavior: smooth;\n}\n\nbody {\n	background: var(--skn-cream);\n	color: var(--skn-ink);\n	font-family: var(--skn-sans);\n	font-size: 17px;\n	line-height: 1.75;\n	-webkit-font-smoothing: antialiased;\n}\n\n::selection {\n	background: var(--skn-terra);\n	color: var(--skn-cream);\n}\n\nh1, h2, h3, h4, h5, h6,\n.site-title,\n.entry-title,\n.page-title {\n	font-family: var(--skn-serif);\n	color: var(--skn-green);\n	line-height: 1.08;\n	letter-spacing: -0.02em;\n}\n\na {\n	color: var(--skn-green);\n	text-decoration-thickness: 1px;\n	text-underline-offset: 3px;\n}\n\na:hover,\na:focus {\n	color: var(--skn-terra);\n}\n\n/* ---------------------------------------------------------\n   Header\n   --------------------------------------------------------- */\n\n.site-header {\n	max-width: 1240px !important;\n	margin: 0 auto !important;\n	padding: 22px 32px !important;\n	display: flex !important;\n	align-items: center;\n	gap: 18px;\n	position: sticky;\n	top: 0;\n	z-index: 100;\n	background: rgba(247, 241, 230, 0.96);\n	backdrop-filter: blur(12px);\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.site-header > .site-logo {\n	width: auto !important;\n	padding: 0 !important;\n	border: 0 !important;\n	margin: 0 !important;\n	flex: 0 0 auto;\n}\n\n.site-header .custom-logo {\n	width: 54px;\n	height: 54px;\n	max-height: 54px;\n	max-width: 54px;\n	object-fit: contain;\n	border-radius: 50%;\n}\n\n.site-branding {\n	margin: 0 !important;\n	flex: 1 1 auto;\n	min-width: 0;\n}\n\n.site-title {\n	font-size: 26px !important;\n	line-height: 1.05 !important;\n	margin: 0 !important;\n	letter-spacing: -0.02em;\n}\n\n.site-title a {\n	color: var(--skn-green) !important;\n	text-decoration: none;\n}\n\n.site-description {\n	margin: 5px 0 0 !important;\n	font-size: 11px !important;\n	letter-spacing: 0.16em;\n	text-transform: uppercase;\n	color: var(--skn-muted) !important;\n	line-height: 1.4;\n}\n\n.primary-navigation {\n	margin-left: auto;\n}\n\n@media only screen and (min-width: 822px) {\n	#primary-menu-list {\n		display: flex;\n		align-items: center;\n		gap: 28px;\n		margin: 0;\n		padding: 0;\n		list-style: none;\n	}\n\n	#primary-menu-list li {\n		margin: 0;\n	}\n\n	#primary-menu-list a {\n		font-size: 12px;\n		font-weight: 600;\n		letter-spacing: 0.12em;\n		text-transform: uppercase;\n		text-decoration: none;\n		color: var(--skn-green);\n		padding: 6px 0;\n		position: relative;\n	}\n\n	#primary-menu-list a::after {\n		content: \"\";\n		position: absolute;\n		left: 0;\n		right: 0;\n		bottom: 0;\n		height: 2px;\n		background: var(--skn-terra);\n		transform: scaleX(0);\n		transform-origin: left;\n		transition: transform 0.2s ease;\n	}\n\n	#primary-menu-list a:hover::after,\n	#primary-menu-list .current-menu-item > a::after {\n		transform: scaleX(1);\n	}\n\n	#primary-menu-list .current-menu-item > a {\n		color: var(--skn-terra);\n	}\n\n	.menu-button-container {\n		display: none;\n	}\n}\n\n/* ---------------------------------------------------------\n   Home layout\n   --------------------------------------------------------- */\n\nbody.home .site-content {\n	padding: 0 !important;\n}\n\nbody.home .content-area,\nbody.home .site-main {\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 0 !important;\n}\n\nbody.home .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\nbody.home .entry-content .wp-block-group__inner-container > *,\nbody.home .entry-content .wp-block-columns,\nbody.home .entry-content .wp-block-column,\nbody.home .entry-content .wp-block-latest-posts {\n	max-width: none !important;\n}\n\n.skn-container {\n	max-width: 1200px !important;\n	margin-left: auto !important;\n	margin-right: auto !important;\n	padding-left: 32px;\n	padding-right: 32px;\n	box-sizing: border-box;\n}\n\n.skn-container > .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Hero\n   --------------------------------------------------------- */\n\n.skn-hero {\n	background:\n		radial-gradient(circle at 82% 18%, rgba(227, 178, 60, 0.18), transparent 32%),\n		radial-gradient(circle at 12% 88%, rgba(217, 119, 87, 0.16), transparent 36%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green) 60%, #1b4d42);\n	color: var(--skn-cream);\n	padding: 92px 0 96px;\n	position: relative;\n	overflow: hidden;\n}\n\n.skn-hero::before {\n	content: \"\";\n	position: absolute;\n	inset: 0;\n	background-image: radial-gradient(rgba(247, 241, 230, 0.08) 1px, transparent 1px);\n	background-size: 26px 26px;\n	opacity: 0.35;\n	pointer-events: none;\n}\n\n.skn-hero-inner {\n	position: relative;\n	z-index: 1;\n}\n\n.skn-hero-cols {\n	align-items: center;\n	gap: 48px;\n}\n\n.skn-hero-copy {\n	padding-right: 20px;\n}\n\n.skn-hero-kicker {\n	font-size: 11px;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-mustard);\n	margin: 0 0 18px;\n	font-weight: 700;\n}\n\n.skn-hero-title {\n	font-size: clamp(56px, 7vw, 104px) !important;\n	line-height: 0.92 !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 22px !important;\n	letter-spacing: -0.045em !important;\n}\n\n.skn-hero-tagline {\n	font-family: var(--skn-serif);\n	font-size: clamp(22px, 2.4vw, 32px);\n	font-style: italic;\n	color: var(--skn-cream) !important;\n	margin: 0 0 18px;\n	line-height: 1.2;\n}\n\n.skn-hero-text {\n	font-size: 17px;\n	line-height: 1.75;\n	color: rgba(247, 241, 230, 0.78);\n	max-width: 520px;\n	margin: 0 0 32px;\n}\n\n.skn-hero-buttons {\n	gap: 14px;\n}\n\n.skn-btn .wp-block-button__link {\n	border-radius: 999px;\n	padding: 14px 26px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease, color 0.2s ease;\n}\n\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link,\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link:not(:hover):not(:active) {\n	background-color: var(--skn-terra) !important;\n	color: var(--skn-cream) !important;\n	border-color: var(--skn-terra) !important;\n}\n\n.skn-hero-buttons .skn-btn-primary .wp-block-button__link:hover {\n	background-color: var(--skn-mustard) !important;\n	color: var(--skn-green-deep) !important;\n	border-color: var(--skn-mustard) !important;\n	transform: translateY(-2px);\n}\n\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link,\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:not(:hover):not(:active) {\n	background-color: transparent !important;\n	color: var(--skn-cream) !important;\n	border-color: rgba(247, 241, 230, 0.45) !important;\n}\n\n.skn-hero-buttons .skn-btn-ghost .wp-block-button__link:hover {\n	background-color: var(--skn-cream) !important;\n	color: var(--skn-green) !important;\n	border-color: var(--skn-cream) !important;\n	transform: translateY(-2px);\n}\n\n.skn-hero-visual {\n	display: flex;\n	justify-content: flex-end;\n}\n\n.skn-hero-poster {\n	margin: 0 !important;\n	width: min(100%, 420px);\n	transform: rotate(2.5deg);\n}\n\n.skn-hero-poster img {\n	width: 100%;\n	height: auto;\n	border: 10px solid var(--skn-cream);\n	border-radius: 6px;\n	box-shadow: 0 30px 70px rgba(0, 0, 0, 0.35);\n	display: block;\n}\n\n/* ---------------------------------------------------------\n   Values\n   --------------------------------------------------------- */\n\n.skn-values {\n	background: var(--skn-cream);\n	padding: 64px 0 56px;\n	border-bottom: 1px solid var(--skn-line);\n}\n\n.skn-values-grid {\n	gap: 0;\n}\n\n.skn-values-grid .wp-block-column {\n	padding: 0 28px;\n	border-left: 1px solid var(--skn-line);\n}\n\n.skn-values-grid .wp-block-column:first-child {\n	border-left: 0;\n	padding-left: 0;\n}\n\n.skn-value-num {\n	font-family: var(--skn-serif);\n	font-size: 14px;\n	color: var(--skn-terra);\n	letter-spacing: 0.1em;\n	margin: 0 0 10px;\n}\n\n.skn-value-title {\n	font-size: 30px !important;\n	margin: 0 0 8px !important;\n}\n\n.skn-values p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0;\n	line-height: 1.65;\n}\n\n/* ---------------------------------------------------------\n   Programs\n   --------------------------------------------------------- */\n\n.skn-programs {\n	background: var(--skn-cream-soft);\n	padding: 96px 0;\n}\n\n.skn-section-head {\n	max-width: 720px !important;\n	margin: 0 0 44px !important;\n}\n\n.skn-kicker {\n	font-size: 11px;\n	font-weight: 700;\n	letter-spacing: 0.24em;\n	text-transform: uppercase;\n	color: var(--skn-terra);\n	margin: 0 0 12px;\n}\n\n.skn-section-title {\n	font-size: clamp(36px, 4vw, 56px) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-section-lead {\n	font-size: 17px;\n	color: var(--skn-muted);\n	line-height: 1.7;\n	margin: 0;\n	max-width: 620px;\n}\n\n.skn-card-grid {\n	gap: 24px;\n	align-items: stretch;\n}\n\n.skn-card-grid .wp-block-column {\n	display: flex;\n}\n\n.skn-card {\n	background: var(--skn-cream);\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 30px 28px 26px !important;\n	width: 100%;\n	display: flex;\n	flex-direction: column;\n	transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;\n}\n\n.skn-card:hover {\n	transform: translateY(-6px);\n	box-shadow: 0 18px 40px rgba(18, 59, 50, 0.1);\n	border-color: rgba(217, 119, 87, 0.45);\n}\n\n.skn-card-num {\n	font-family: var(--skn-serif);\n	font-size: 13px;\n	letter-spacing: 0.12em;\n	color: var(--skn-terra);\n	margin: 0 0 22px;\n}\n\n.skn-card h3 {\n	font-size: 25px !important;\n	margin: 0 0 10px !important;\n	line-height: 1.15 !important;\n}\n\n.skn-card p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	margin: 0 0 18px;\n	line-height: 1.65;\n}\n\n.skn-card-link {\n	margin-top: auto !important;\n}\n\n.skn-card-link a,\n.skn-section-link a {\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.1em;\n	text-transform: uppercase;\n	text-decoration: none;\n	color: var(--skn-terra);\n	border-bottom: 1px solid rgba(217, 119, 87, 0.4);\n	padding-bottom: 2px;\n}\n\n.skn-card-link a:hover,\n.skn-section-link a:hover {\n	color: var(--skn-green);\n	border-color: var(--skn-green);\n}\n\n/* ---------------------------------------------------------\n   Works\n   --------------------------------------------------------- */\n\n.skn-works {\n	background: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-works-grid {\n	gap: 56px;\n}\n\n.skn-works .skn-section-title {\n	font-size: clamp(34px, 4vw, 52px) !important;\n}\n\n.skn-latest {\n	display: block !important;\n	margin: 0 !important;\n	padding: 0 !important;\n	list-style: none !important;\n}\n\n.skn-latest li {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 20px;\n	overflow: hidden;\n	padding: 0 !important;\n	margin: 0 !important;\n	box-shadow: 0 18px 50px rgba(18, 59, 50, 0.08);\n	display: grid;\n	grid-template-columns: 42% 1fr;\n	align-items: stretch;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image {\n	margin: 0 !important;\n	grid-row: 1 / span 2;\n	background: var(--skn-green);\n	padding: 18px;\n	display: flex;\n	align-items: center;\n	justify-content: center;\n}\n\n.skn-latest .wp-block-latest-posts__featured-image img {\n	width: 100% !important;\n	height: auto !important;\n	max-height: 420px;\n	object-fit: contain;\n	display: block;\n	box-shadow: 0 14px 30px rgba(0, 0, 0, 0.28);\n}\n\n.skn-latest .wp-block-latest-posts__post-title {\n	display: block;\n	font-family: var(--skn-serif);\n	font-size: 30px;\n	line-height: 1.15;\n	color: var(--skn-green);\n	text-decoration: none;\n	padding: 28px 30px 0;\n}\n\n.skn-latest .wp-block-latest-posts__post-title:hover {\n	color: var(--skn-terra);\n}\n\n.skn-latest .wp-block-latest-posts__post-excerpt {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	padding: 10px 30px 28px;\n	margin: 0 !important;\n}\n\n/* ---------------------------------------------------------\n   Agenda\n   --------------------------------------------------------- */\n\n.skn-agenda {\n	background:\n		radial-gradient(circle at 90% 10%, rgba(227, 178, 60, 0.16), transparent 30%),\n		linear-gradient(135deg, var(--skn-green-deep), var(--skn-green));\n	color: var(--skn-cream);\n	padding: 96px 0;\n}\n\n.skn-agenda .skn-section-title {\n	color: var(--skn-cream) !important;\n}\n\n.skn-agenda .skn-kicker {\n	color: var(--skn-mustard);\n}\n\n.skn-agenda .skn-section-lead {\n	color: rgba(247, 241, 230, 0.75);\n}\n\n.skn-agenda .skn-section-link a {\n	color: var(--skn-mustard);\n	border-color: rgba(227, 178, 60, 0.5);\n}\n\n.skn-agenda .skn-section-link a:hover {\n	color: var(--skn-cream);\n	border-color: var(--skn-cream);\n}\n\n.skn-latest-agenda li {\n	background: #fffaf2;\n}\n\n/* ---------------------------------------------------------\n   CTA\n   --------------------------------------------------------- */\n\n.skn-cta {\n	background:\n		radial-gradient(circle at 15% 20%, rgba(247, 241, 230, 0.12), transparent 30%),\n		var(--skn-terra);\n	color: var(--skn-cream);\n	padding: 88px 0;\n	text-align: center;\n}\n\n.skn-cta-inner {\n	max-width: 820px !important;\n}\n\n.skn-cta .skn-kicker {\n	color: var(--skn-green-deep);\n}\n\n.skn-cta-title {\n	font-size: clamp(40px, 5vw, 64px) !important;\n	color: var(--skn-cream) !important;\n	margin: 0 0 16px !important;\n}\n\n.skn-cta-text {\n	font-size: 18px;\n	color: rgba(247, 241, 230, 0.85);\n	max-width: 620px;\n	margin: 0 auto 28px;\n}\n\n.skn-cta-actions {\n	margin: 0 0 24px !important;\n}\n\n.skn-cta-button {\n	display: inline-block;\n	background: var(--skn-cream);\n	color: var(--skn-green) !important;\n	border-radius: 999px;\n	padding: 14px 30px;\n	font-size: 12px;\n	font-weight: 700;\n	letter-spacing: 0.12em;\n	text-transform: uppercase;\n	text-decoration: none;\n	transition: transform 0.2s ease, background 0.2s ease;\n}\n\n.skn-cta-button:hover {\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	transform: translateY(-2px);\n}\n\n.skn-cta-location {\n	font-size: 11px;\n	letter-spacing: 0.18em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.65);\n	margin: 0;\n}\n\n/* ---------------------------------------------------------\n   Required pages\n   --------------------------------------------------------- */\n\n.page .site-main,\n.single .site-main {\n	padding-top: 0;\n}\n\n.page .entry-header,\n.single .entry-header {\n	max-width: 900px !important;\n	margin: 56px auto 0 !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-title,\n.single .entry-title {\n	font-size: clamp(42px, 6vw, 72px) !important;\n	line-height: 0.98 !important;\n	margin: 0 !important;\n	color: var(--skn-green);\n}\n\n.page .entry-content,\n.single .entry-content {\n	max-width: 760px !important;\n	margin: 32px auto 72px !important;\n	padding: 0 32px !important;\n}\n\n.page .entry-content > *,\n.single .entry-content > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.page .entry-content .wp-block-group__inner-container > *,\n.single .entry-content .wp-block-group__inner-container > * {\n	max-width: none !important;\n	margin-left: 0 !important;\n	margin-right: 0 !important;\n}\n\n.skn-required-page {\n	position: relative;\n}\n\n.skn-page-heading {\n	font-size: clamp(34px, 4.5vw, 52px) !important;\n	margin: 0 0 18px !important;\n}\n\n.skn-lead {\n	font-size: 20px !important;\n	line-height: 1.7 !important;\n	color: var(--skn-ink) !important;\n}\n\n.skn-note-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-terra);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-size: 16px !important;\n	font-weight: 600;\n	color: var(--skn-green) !important;\n	margin: 28px 0 0 !important;\n}\n\n.skn-verify-line {\n	border-left-color: var(--skn-mustard);\n	background: var(--skn-green);\n	color: var(--skn-cream) !important;\n	font-family: ui-monospace, SFMono-Regular, Consolas, monospace;\n	letter-spacing: 0.02em;\n}\n\n.skn-verify-line::before {\n	content: \"✓ \";\n	color: var(--skn-mustard);\n}\n\n/* ---------------------------------------------------------\n   Single posts\n   --------------------------------------------------------- */\n\n.single .entry-header .post-thumbnail {\n	display: none !important;\n}\n\n.single .entry-content p {\n	font-size: 18px;\n	line-height: 1.85;\n}\n\n.skn-post-image {\n	margin: 36px 0 !important;\n}\n\n.skn-post-image img {\n	border-radius: 16px;\n	box-shadow: 0 20px 50px rgba(18, 59, 50, 0.15);\n}\n\n.skn-schedule-line {\n	background: #fffaf2;\n	border-left: 4px solid var(--skn-mustard);\n	border-radius: 0 12px 12px 0;\n	padding: 16px 20px !important;\n	font-weight: 700;\n	color: var(--skn-green) !important;\n	margin-top: 28px !important;\n}\n\n.single .entry-footer {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 24px 32px 0 !important;\n	border-top: 1px solid var(--skn-line);\n	font-size: 13px;\n	color: var(--skn-muted);\n}\n\n.single .entry-footer .posted-by {\n	margin-bottom: 8px;\n}\n\n.single .entry-footer .post-taxonomies {\n	margin-top: 8px;\n}\n\n.single .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n.single .author-bio {\n	max-width: 760px !important;\n	margin: 0 auto 72px !important;\n	padding: 0 32px !important;\n}\n\n/* ---------------------------------------------------------\n   Blog & archives\n   --------------------------------------------------------- */\n\n.blog .site-main,\n.archive .site-main {\n	max-width: 1100px !important;\n	margin: 0 auto !important;\n	padding: 0 32px 80px !important;\n}\n\n.blog .page-header,\n.archive .page-header {\n	max-width: 100% !important;\n	margin: 56px 0 32px !important;\n	padding: 0 !important;\n}\n\n.blog .page-title,\n.archive .page-title {\n	font-size: clamp(36px, 4.5vw, 56px) !important;\n	margin: 0 !important;\n}\n\n.archive .page-header .archive-description,\n.archive .page-header .archive-description p {\n	font-family: var(--skn-sans) !important;\n	font-size: 17px !important;\n	line-height: 1.7 !important;\n	color: var(--skn-muted) !important;\n	max-width: 720px;\n	margin: 12px 0 0 !important;\n}\n\n.blog article,\n.archive article {\n	background: #fffaf2;\n	border: 1px solid var(--skn-line);\n	border-radius: 18px;\n	padding: 24px !important;\n	margin-bottom: 24px;\n	display: grid;\n	grid-template-columns: 200px 1fr;\n	grid-template-rows: auto auto auto;\n	gap: 0 28px;\n	align-items: start;\n	align-content: start;\n}\n\n.blog article .entry-header,\n.archive article .entry-header {\n	display: contents;\n}\n\n.blog article .entry-header .post-thumbnail,\n.archive article .entry-header .post-thumbnail {\n	grid-column: 1;\n	grid-row: 1 / span 3;\n	margin: 0 !important;\n}\n\n.blog article .entry-header .post-thumbnail img,\n.archive article .entry-header .post-thumbnail img {\n	border-radius: 12px;\n	width: 100%;\n	height: auto;\n	max-height: 280px;\n	object-fit: cover;\n}\n\n.blog article .entry-header .entry-title,\n.archive article .entry-header .entry-title {\n	grid-column: 2;\n	grid-row: 1;\n	font-size: 28px !important;\n	margin: 0 !important;\n	align-self: start;\n}\n\n.blog article .entry-header .entry-title a,\n.archive article .entry-header .entry-title a {\n	text-decoration: none;\n}\n\n.blog article .entry-header .entry-title a:hover,\n.archive article .entry-header .entry-title a:hover {\n	text-decoration: underline;\n}\n\n.blog article .entry-content,\n.archive article .entry-content {\n	grid-column: 2;\n	grid-row: 2;\n	margin: 8px 0 0 !important;\n	max-width: none !important;\n}\n\n.blog article .entry-content p,\n.archive article .entry-content p {\n	font-size: 15px;\n	color: var(--skn-muted);\n	line-height: 1.65;\n	margin: 0;\n}\n\n.blog article .entry-footer,\n.archive article .entry-footer {\n	grid-column: 2;\n	grid-row: 3;\n	margin: 12px 0 0 !important;\n	padding: 0 !important;\n	border: 0 !important;\n	font-size: 12px;\n	color: var(--skn-muted);\n}\n\n.blog article .entry-footer a,\n.archive article .entry-footer a {\n	color: var(--skn-terra);\n	text-decoration: none;\n}\n\n/* ---------------------------------------------------------\n   Footer\n   --------------------------------------------------------- */\n\n.site-footer {\n	max-width: none !important;\n	margin: 0 !important;\n	padding: 48px 0 36px !important;\n	background: var(--skn-green-deep);\n	color: var(--skn-cream);\n}\n\n.site-footer > .footer-navigation,\n.site-footer > .site-info {\n	max-width: 1200px;\n	margin-left: auto;\n	margin-right: auto;\n	padding-left: 32px;\n	padding-right: 32px;\n}\n\n.site-footer .footer-navigation {\n	text-align: left;\n	margin: 0 0 20px;\n}\n\n.site-footer .footer-navigation-wrapper {\n	display: flex;\n	justify-content: flex-start !important;\n	gap: 24px;\n	list-style: none;\n	margin: 0;\n	padding: 0;\n}\n\n.site-footer .footer-navigation-wrapper li {\n	line-height: 1.2;\n	margin: 0;\n}\n\n.site-footer .footer-navigation-wrapper li a,\n.site-footer .footer-navigation-wrapper li a:link,\n.site-footer .footer-navigation-wrapper li a:visited,\n.site-footer .footer-navigation-wrapper li a:active {\n	color: rgba(247, 241, 230, 0.72) !important;\n	font-size: 11px;\n	letter-spacing: 0.14em;\n	text-transform: uppercase;\n	text-decoration: none;\n	padding: 6px 0;\n}\n\n.site-footer .footer-navigation-wrapper li a:hover {\n	color: var(--skn-mustard) !important;\n}\n\n.site-footer > .site-info {\n	border-top: 1px solid rgba(247, 241, 230, 0.18);\n	padding-top: 24px;\n	display: flex;\n	align-items: center;\n	justify-content: space-between;\n	gap: 16px;\n}\n\n.site-footer .site-info .site-name {\n	font-family: var(--skn-serif);\n	font-size: 18px;\n}\n\n.site-footer .site-info .site-logo .custom-logo {\n	width: 44px;\n	height: 44px;\n	max-height: 44px;\n}\n\n.site-footer .powered-by,\n.site-footer .privacy-policy {\n	display: none !important;\n}\n\n.site-footer .site-info::after {\n	content: \"Ruang kreasi dan berbagi ide\";\n	font-size: 12px;\n	letter-spacing: 0.08em;\n	text-transform: uppercase;\n	color: rgba(247, 241, 230, 0.55);\n}\n\n/* ---------------------------------------------------------\n   Responsive\n   --------------------------------------------------------- */\n\n@media (max-width: 1024px) {\n	.skn-hero-title {\n		font-size: clamp(48px, 8vw, 76px) !important;\n	}\n\n	.skn-hero-cols {\n		gap: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 340px);\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 420px;\n	}\n}\n\n@media (max-width: 821px) {\n	.site-header {\n		position: relative;\n		flex-wrap: wrap;\n		padding: 16px 20px !important;\n		gap: 12px;\n	}\n\n	.site-header .custom-logo {\n		width: 44px;\n		height: 44px;\n	}\n\n	.site-title {\n		font-size: 22px !important;\n	}\n\n	.site-description {\n		font-size: 10px !important;\n	}\n\n	.primary-navigation {\n		width: 100%;\n		margin-left: 0;\n	}\n\n	.skn-container {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.skn-hero {\n		padding: 56px 0 64px;\n	}\n\n	.skn-hero-cols {\n		flex-direction: column;\n	}\n\n	.skn-hero-copy {\n		padding-right: 0;\n	}\n\n	.skn-hero-visual {\n		justify-content: flex-start;\n		margin-top: 32px;\n	}\n\n	.skn-hero-poster {\n		width: min(100%, 320px);\n		transform: rotate(1.5deg);\n	}\n\n	.skn-values {\n		padding: 40px 0;\n	}\n\n	.skn-values-grid .wp-block-column {\n		border-left: 0;\n		border-top: 1px solid var(--skn-line);\n		padding: 20px 0 0;\n		margin-top: 20px;\n	}\n\n	.skn-values-grid .wp-block-column:first-child {\n		border-top: 0;\n		margin-top: 0;\n		padding-top: 0;\n	}\n\n	.skn-programs,\n	.skn-works,\n	.skn-agenda {\n		padding: 64px 0;\n	}\n\n	.skn-card-grid {\n		flex-direction: column;\n	}\n\n	.skn-card-grid .wp-block-column {\n		width: 100%;\n	}\n\n	.skn-works-grid,\n	.skn-agenda-grid {\n		flex-direction: column;\n		gap: 32px;\n	}\n\n	.skn-works-grid .wp-block-column,\n	.skn-agenda-grid .wp-block-column {\n		width: 100% !important;\n		flex-basis: 100% !important;\n	}\n\n	.skn-latest li {\n		grid-template-columns: 1fr;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image {\n		grid-row: auto;\n	}\n\n	.skn-latest .wp-block-latest-posts__featured-image img {\n		max-height: 380px;\n	}\n\n	.skn-cta {\n		padding: 64px 0;\n	}\n\n	.page .entry-header,\n	.single .entry-header {\n		margin-top: 32px !important;\n		padding: 0 20px !important;\n	}\n\n	.page .entry-content,\n	.single .entry-content {\n		padding: 0 20px !important;\n		margin-top: 24px !important;\n	}\n\n	.page .entry-title,\n	.single .entry-title {\n		font-size: clamp(34px, 9vw, 48px) !important;\n	}\n\n	.blog .site-main,\n	.archive .site-main {\n		padding: 0 20px 64px !important;\n	}\n\n	.blog article,\n	.archive article {\n		grid-template-columns: 1fr;\n		padding: 20px !important;\n	}\n\n	.blog article .entry-header,\n	.archive article .entry-header {\n		display: block;\n	}\n\n	.blog article .entry-header .post-thumbnail,\n	.archive article .entry-header .post-thumbnail {\n		margin-bottom: 16px !important;\n	}\n\n	.blog article .entry-header .entry-title,\n	.archive article .entry-header .entry-title {\n		font-size: 26px !important;\n	}\n\n	.site-footer > .footer-navigation,\n	.site-footer > .site-info {\n		padding-left: 20px;\n		padding-right: 20px;\n	}\n\n	.site-footer > .site-info {\n		flex-direction: column;\n		align-items: flex-start;\n	}\n\n	.site-footer .site-info::after {\n		margin-top: 8px;\n	}\n}\n','twentytwentyone','','inherit','closed','closed','','27-revision-v1','','','2026-10-27 19:21:04','2026-10-27 11:21:04','',27,'http://localhost:8080/?p=33',0,'revision','',0),
